-- 206: Czech and Slovak names follow 국립국어원 체코어 표기법 (the Slovak names
-- too, which have no table of their own):
--   Alexander Dubček        알렉산드르 두브체크 → 알렉산데르 둡체크 (b before a voiceless consonant is a 받침)
--   Gustáv Husák            구스타우 → 구스타프 (final v 프)
--   Jan Pauer               파우어 → 파우에르;  Pavel Auersperg  아우에스페르크 → 아우에르스페르크
--   Jaroslav Seifert        셰이페르트 → 세이페르트 (s is ㅅ, not š)
--   Jiří Hájek, Jiří Gruntorád, Jiřina Šiklová   지리·지르지 → 이르지 (j is 이, ř before a vowel 르ㅈ)
--   Vasiľ Biľak             바실리 → 바실;  Vojtěch Mastný  보이텍 → 보이테흐 (ch 흐)
--   Zdeněk Mlynář           즈데녜크 믈리나르 → 즈데네크 믈리나르시 (consonant + ě is 에, final ř 르시)
--   Tomáš Garrigue Masaryk  가리크 → 가리그, as Jan Garrigue Masaryk already has it
-- Misspelled aliases are dropped. Every replacement keeps the particle
-- (the new final syllable is as open or closed as the old one).
-- Also: Aleksandar Ranković's partisan name 마르코 is removed as a one-word
-- alias; it linked every other Marko to his card.

BEGIN;
DELETE FROM commulingo_person_aliases WHERE person_id = 'aleksandar-rankovic' AND lang = 'ko' AND alias = '마르코';

UPDATE commulingo_people SET name_ko = '알렉산데르 둡체크', given_name_ko = '알렉산데르', family_name_ko = '둡체크',
    link_expressions = replace(link_expressions::text, '두브체크', '둡체크')::jsonb WHERE id = 'dubcek';
UPDATE commulingo_person_aliases SET alias = '둡체크' WHERE person_id = 'dubcek' AND lang = 'ko' AND alias = '두브체크';
UPDATE commulingo_people SET name_ko = '구스타프 후사크', given_name_ko = '구스타프' WHERE id = 'gustav-husak';
UPDATE commulingo_people SET name_ko = '얀 파우에르', family_name_ko = '파우에르' WHERE id = 'jan-pauer';
UPDATE commulingo_people SET name_ko = '야로슬라프 세이페르트', family_name_ko = '세이페르트' WHERE id = 'jaroslav-seifert';
UPDATE commulingo_people SET name_ko = '이르지 하예크', given_name_ko = '이르지' WHERE id = 'jiri-hajek';
UPDATE commulingo_people SET name_ko = '파벨 아우에르스페르크', family_name_ko = '아우에르스페르크' WHERE id = 'pavel-auersperg';
UPDATE commulingo_people SET name_ko = '바실 빌랴크', given_name_ko = '바실' WHERE id = 'vasil-bilak';
UPDATE commulingo_people SET name_ko = '보이테흐 마스트니', given_name_ko = '보이테흐' WHERE id = 'vojtech-mastny';
UPDATE commulingo_people SET name_ko = '즈데네크 믈리나르시', given_name_ko = '즈데네크' WHERE id = 'zdenek-mlynar';
UPDATE commulingo_people SET name_ko = '토마시 가리그 마사리크', given_name_ko = '토마시 가리그' WHERE id = 'tomas-garrigue-masaryk';
DELETE FROM commulingo_person_aliases WHERE lang = 'ko' AND (person_id, alias) IN (
    ('gustav-husak', '구스타우 후사크'), ('jaroslav-seifert', '야로슬라프 셰이퍼르트'), ('jiri-hajek', '지리 하예크'),
    ('vojtech-mastny', '보이체흐 마스트니'), ('zdenek-mlynar', '즈데네크 믈리나르'), ('zdenek-mlynar', '즈데녜크 뮐러'),
    ('alois-indra', '알로이즈 인드라'), ('jan-patocka', '얀 파토츠카'), ('ota-sik', '오타 쉬크'),
    ('stanislav-cecek', '스타니슬라프 체첵'));

UPDATE commulingo_people SET bio_ko = $q$슬로바키아 출신 공산주의 법률가. 반나치 슬로바키아 민족봉기 지도부에서 활동했고, 전후 슬로바키아 행정을 장악했으나 1950년 '부르주아 민족주의' 혐의로 종신형을 받았다. 1963년 복권되어 둡체크의 프라하의 봄에서 부총리를 지냈지만, 소련 침공 후 입장을 선회해 개혁파 숙청을 주도했다. 1969년부터 1987년까지 당 총서기, 1975년부터 1989년까지 대통령으로서 20년간 '정상화' 체제를 이끌며 상대적 생활안정과 비밀경찰 탄압을 병행했다. 1989년 벨벳 혁명으로 41년 만의 비공산 내각에 정권을 넘기고 물러났다.$q$ WHERE id = $q$gustav-husak$q$;
UPDATE commulingo_people SET bio_ko = $q$체코슬로바키아 공산당원으로 스페인 내전에 의용군으로 참전했고, 1948년 쿠데타에서는 민병대를 지휘했다. 내무차관으로 공포정치에 가담했으나 1951년 체포되어 슬란스키 사건에 연루된 혐의로 고문과 25년형을 받았고, 1955년 무죄 석방되었다. 1968년 프라하의 봄에서 내무장관으로 복귀해 국가보안대(StB) 개혁을 추진하고 KGB 연락장교 6명의 존재를 폭로했으나, 부하인 빌리암 샬고비치가 KGB와 공모해 침공 당일 둡체크 체포를 지원하면서 개혁은 무너졌다.$q$ WHERE id = $q$josef-pavel$q$;
UPDATE commulingo_people SET bio_ko = $q$체코슬로바키아의 개혁공산주의 정치인으로, 프라하의 봄에서 둡체크의 가장 중요한 정치적 동맹이었다. 나치 점령기 체코민족평의회 부의장으로 프라하 봉기를 이끌었고, 1948년 2월 쿠데타에서 인민민병대를 지휘했으며, 1951년 슬란스키 사건 연루로 종신형을 선고받았다가 1963년 복권되어 1968년 국민의회 의장이 되었다. 1968년 1월 『루데 프라보』 인터뷰로 개혁의 신호탄을 쏘아올렸고, 8월 침공 후 모스크바로 끌려가 의정서 서명을 강요당했으며, 귀환 후 후사크에 의해 축출되어 감시 속에 사망했다.$q$ WHERE id = $q$josef-smrkovsky$q$;
UPDATE commulingo_people SET bio_ko = $q$오스트리아-헝가리군에서 탈영해 체코슬로바키아 군단에 합류한 1차대전 참전자로, 2차대전에서는 소련에서 체코슬로바키아 군단을 조직해 동부전선을 누비며 국민영웅으로 떠올랐다. 1948년 국방장관으로서 '군대는 인민을 향해 진군하지 않을 것'이라 선언하며 공산당의 2월 쿠데타를 방조했으나, 곧 숙청당해 1950년대를 수감과 은둔으로 보냈다. 1968년 3월 둡체크의 추천으로 대통령에 당선되어 프라하의 봄 개혁에 동의했고, 8월 바르샤바조약군 침공 직후 모스크바에서 브레즈네프 앞에서 권총 자살을 위협하며 납치된 개혁파 지도부의 석방을 이끌어냈다. 이후 정상화 국면에서 신문 검열에 협력하고 둡체크 교체를 방조하는 등 소극적 순응으로 일관하다 1975년 헌법 조항으로 물러났다.$q$ WHERE id = $q$ludvik-svoboda$q$;
UPDATE commulingo_people SET bio_ko = $q$1921년 KSČ 창립 당원이자 자물쇠공 출신으로, 슬란스키 숙청 과정에서 당 기구를 타고 부상했으며, 고트발트 사후 제1서기(1953–1968)와 대통령(1957–1968)을 겸직하며 15년간 체코슬로바키아를 통치했다. 스탈린주의 정통을 고수하며 중앙계획·검열을 강화하고 1950년대 정치재판 청산을 거부했으나, 경제 침체와 슬로바키아의 불만이 누적되며 정권 기반이 잠식되었다. 1968년 1월 둡체크에게 당직을 내주며 강제 사임함으로써 개혁의 최대 장애물이 제거되었고, 이는 곧바로 프라하의 봄을 촉발했다. 1971년 정상화 국면에서 중앙위원으로 재선되었으나 실질적 영향력은 없었고, 1975년 프라하에서 사망했다.$q$ WHERE id = $q$antonin-novotny$q$;
UPDATE commulingo_people SET bio_ko = $q$이르지 하예크는 체코슬로바키아의 정치가이자 외교관으로, 프라하의 봄 개혁과 그 좌절을 모두 경험했다. 1968년 소련 주도의 침공을 유엔에서 점령이라고 규정하며 항의한 뒤 관직과 공산당 지위를 잃었고, 국제적 약속이 국내 권력보다 어떤 의미를 가질 수 있는지 보여 주었다. 그는 1977년 바츨라프 하벨, 얀 파토치카와 함께 샤르타 77의 첫 대변인이 되어 헬싱키 최종의정서의 인권 조항을 시민적 책임의 근거로 제시했다.$q$ WHERE id = $q$jiri-hajek$q$;
UPDATE commulingo_people SET bio_ko = $q$체코슬로바키아의 개혁공산주의 총리(1968~1970). 광산 노동자 출신 기술관료로, 연료·에너지 장관과 국가계획위원회 의장을 거쳐 1968년 4월 행동강령을 채택한 당 중앙위 전원회의에서 총리로 임명되었다. 둡체크와 함께 프라하의 봄을 이끌었고, 8월 침공 후 소련에 연행되어 모스크바 의정서에 서명했다. 귀국 후 개혁 지속을 약속했으나, 후사크 체제 아래 1970년 해임·제명되고 20년간 연구소 부소장으로 밀려났다.$q$ WHERE id = $q$oldrich-cernik$q$;
UPDATE commulingo_people SET bio_ko = $q$체코슬로바키아의 경제학자이자 정치인으로, 프라하의 봄 경제 개혁의 설계자였다. 1964년 저서에서 사회주의 계획경제에 시장 메커니즘을 접목하는 신경제모델을 제시했고, 1967년 12월 중앙위원회에서 노보트니 체제를 공개 비판하며 경제 개혁이 정치적 변화 없이는 불가능하다고 주장했다. 1968년 둡체크 내각에서 부총리로 개혁을 주도했으나, 바르샤바조약군 침공으로 유고슬라비아 망명길에 올랐고 이후 스위스에서 '제3의 길'을 이론화하며 생을 마감했다.$q$ WHERE id = $q$ota-sik$q$;
UPDATE commulingo_people SET bio_ko = $q$슬로바키아 출신 체코슬로바키아 보안기관 장교이자 정치인. 전시에는 친나치 슬로바키아군에서 소련으로 탈주한 후 체코슬로바키아 군단에서 복무했고, 전후 StB 장교로 정치탄압에 가담했다. 1968년 6월, 둡체크는 자신과 개인적 친분이 있는 샬고비치를 내무차관 겸 StB 책임자로 발탁했으나, 샬고비치는 KGB와 협력하여 개혁파 체포 계획을 세우고 8월 21일 둡체크 일행을 소련군에 넘겼다. '정상화' 체제에서는 슬로바키아 민족평의회 의장(1975~1989)이라는 의전직에 머물렀고, 벨벳 혁명 직후 자택 지하실에서 목을 매 자살했다.$q$ WHERE id = $q$viliam-salgovic$q$;
UPDATE commulingo_people SET bio_ko = $q$얀 파우에르는 1968년 프라하의 봄을 목격하고 이듬해 서독으로 이주한 체코 출신 역사가다. 1995년 바르샤바조약군의 체코슬로바키아 침공을 다룬 표준적 저작 『프라하 1968』을 출간했으며, 브레멘대학 동유럽연구소에서 체코슬로바키아 현대사를 연구했다. 2011년 ENRS 기고문에서 그는 침공이 '시민사회 반대운동의 시작이자 개혁공산주의의 역사적 종말'이었다고 평가하며, 프라하의 봄이 소련의 탱크와 탈냉전기 체코의 기억 정치에 의해 두 번 묻혔다고 주장했다.$q$ WHERE id = $q$jan-pauer$q$;
UPDATE commulingo_people SET bio_ko = $q$야로슬라프 세이페르트는 체코슬로바키아의 시인이자 기자로, 프라하의 노동계급 문화와 아방가르드 시를 연결한 작가였다. 그는 1929년 공산당의 관료화와 스탈린주의적 전환에 항의해 당을 떠났지만 좌파적 사회 감각을 버리지 않았다. 1948년 이후 작가 탄압을 조사한 위원회를 이끌었고, 1968년 작가대회에서 검열 폐지와 문화적 개방을 뒷받침했으며, 침공 뒤에도 공개적으로 저항했다. 1984년 노벨 문학상을 받았지만 정상화 체제에서는 작품과 공적 발언이 제한되었다.$q$ WHERE id = $q$jaroslav-seifert$q$;
UPDATE commulingo_people SET bio_ko = $q$보이테흐 마스트니는 체코슬로바키아 출신의 미국 역사학자로, 냉전과 소련 대외정책을 연구했다. 계급 배경 때문에 정규 중등교육 대신 공장 노동과 기록관 실무를 거친 경험은 그의 사료 중심 연구 태도와 맞물렸다. 그는 바르샤바 조약기구를 처음부터 단일한 군사동맹으로 보지 않고, 정치적 협상 수단과 소련의 규율 장치 사이의 긴장 속에서 해석했으며, 공개 기록을 통해 그 실제 작동을 추적했다. 평행사 프로젝트를 이끌며 동구권 군 관계자들의 증언과 문서를 국제 연구 공간에 연결했다.$q$ WHERE id = $q$vojtech-mastny$q$;
UPDATE commulingo_people SET bio_ko = $q$즈데네크 믈리나르시는 체코슬로바키아의 공산주의 정치가이자 법률가로, 사회주의를 민주적 통제와 시민의 능동성에 결합하려 했다. 그는 1968년 프라하의 봄에서 중앙위원회 서기로 일하며 알렉산데르 둡체크 주변의 개혁 지도부에 참여했고, 행동강령을 만든 정치·법률 연구팀의 핵심 인물이었다. 그러나 바르샤바조약군의 침공 뒤 모스크바 의정서에 서명했고 곧 개혁 노선의 한계와 점령의 현실에 부딪혀 당과 공직에서 물러났다. 이후 헌장 77에 서명하고 오스트리아로 망명해 정치학자이자 프라하의 봄을 성찰한 저술가로 활동했다.$q$ WHERE id = $q$zdenek-mlynar$q$;
UPDATE commulingo_people SET moment_ko = $q$1968년 8월 21일 아침, 둡체크는 '인드라 동지가 이끄는 노동자·농민 정부의 이름으로' 체포되었다. 그러나 인드라의 내각은 단 하루도 현실이 되지 못했고, 그가 서명한 초청장은 1990년대에야 공개되었다.$q$ WHERE id = $q$alois-indra$q$;
UPDATE commulingo_people SET moment_ko = $q$1968년 8월 침공 당일, 파벨이 해임한 부하 샬고비치는 KGB와 함께 둡체크를 체포했고, 내무부는 장관의 손을 떠났다.$q$ WHERE id = $q$josef-pavel$q$;
UPDATE commulingo_people SET moment_ko = $q$1968년 8월 모스크바에서 브레즈네프가 '노동자-농민 정부'를 세우라 요구하자, 스보보다는 둡체크와 개혁파 지도부를 석방하지 않으면 내 머리에 총알을 박겠다고 응수했다.$q$ WHERE id = $q$ludvik-svoboda$q$;
UPDATE commulingo_people SET moment_ko = $q$1968년 초, 아우에르스페르크는 프라하의 자기 사무실에서 밀란시르·리흐타·시크와 함께 행동강령 초안을 써 내려갔다.$q$ WHERE id = $q$pavel-auersperg$q$;
UPDATE commulingo_people SET moment_ko = $q$1968년 8월 21일 새벽, 소련군 장교들이 둡체크의 사무실로 들이닥쳐 전화선을 끊고 수갑을 채웠다. 한 장교가 말했다: '필요하다면 체코인 백만 명을 죽여서라도 반혁명을 끝장낼 것이다.'$q$ WHERE id = $q$dubcek$q$;
UPDATE commulingo_people SET epithet_ko = $q$둡체크를 체포해 소련에 넘긴 내무차관$q$ WHERE id = $q$viliam-salgovic$q$;
UPDATE commulingo_person_sections SET body_ko = $q$알렉산데르 둡체크는 1921년 슬로바키아 우흐로베츠에서 태어났다. 사회주의 이상에 이끌린 그의 부모는 1925년 소련 키르기지아의 인테르헬포 협동조합에 합류했고, 둡체크는 프룬제와 고리키에서 소년기를 보냈다. 1938년 슬로바키아로 돌아온 그는 이듬해 비합법 슬로바키아공산당에 입당했고, 1944년 슬로바키아 민족봉기에서 무기를 들고 싸우다 두 차례 부상을 입었으며 형 율리우스를 잃었다. 소련에서 자라고 파시즘과 싸운 이 경력은 그를 누구도 반소주의자로 부를 수 없는 인물로 만들었다.

전후 당 기구에서 성장한 그는 모스크바 고등당학교에서 수학했고, 1963년 슬로바키아공산당 제1서기가 되어 1950년대 정치재판 희생자들의 복권과 슬로바키아의 동등한 지위를 밀고 나갔다. 1968년 1월 5일 중앙위원회는 노보트니를 대신해 그를 체코슬로바키아공산당 제1서기로 선출했다. 4월의 행동강령은 당내 민주주의, 언론 자유, 복권, 연방제, 경제 개혁을 내걸었고, 6월에는 검열이 폐지되었다. 「인간의 얼굴을 한 사회주의」라는 구호 아래 진행된 프라하의 봄은 사회주의의 포기가 아니라 갱신의 시도로 제시되었고, 대중의 열광적 지지를 받았다.

둡체크는 바르샤바조약과 코메콘에 대한 충성을 거듭 확인했으나, 소련과 이웃 당 지도부들은 개혁이 당의 지도적 역할을 침식하고 블록의 안보를 위협한다고 판단해 갔다. 드레스덴 회동, 바르샤바 서한, 치에르나 회담으로 이어진 1968년 여름의 압박은 사회주의 국가들 사이의 관계가 어디까지 대등할 수 있는가라는, 운동 전체의 미해결 문제를 노출시켰다.$q$ WHERE id = $q$234$q$;
UPDATE commulingo_person_sections SET body_ko = $q$모스크바 의정서에 서명한 뒤 체르니크는 총리로서 점령의 제도화를 직접 집행했다. 1968년 10월 3~4일 모스크바에서 열린 체코슬로바키아 대표단 회담(체르니크와 둡체크, 후사크 참석)에서 양국 정부는 소련군의 임시 주둔 협정을 작성·서명하기로 합의했고, 10월 14~15일 코시긴과 체르니크가 이끄는 대표단이 조문을 협상했다. 10월 16일 프라하 체르닌 궁에서 코시긴 등 소련 대표가 협정에 서명했고, 같은 날 체코슬로바키아 정부가 이를 승인한 뒤 10월 17일 의회가 비준했다. 이른바 '곤봉법'(1969년 연방의회 법률조치 제99호, 공공질서 유지를 위한 일시 조치)은 1969년 8월 항의 시위에 대한 대응으로 제정되었으며, 여기에는 체르니크 외에 둡체크와 스보보다 대통령도 서명했다. 이 법으로 1969년 8월 바츨라프 광장 등에서의 시위가 탄압받았다. 체코 역사학계는 이 서명을 체르니크가 프라하의 봄 지도자에서 정상화의 집행자로 전환한 분기점으로 본다.$q$ WHERE id = $q$4736$q$;
UPDATE commulingo_person_sections SET body_ko = $q$시크가 이끈 경제학 연구소의 작업을 토대로 체코슬로바키아 공산당 정부는 1965년 신경제모델을 채택했다. 이 모델은 산업 성장을 되살리려는 제한적 개혁으로, 중앙 계획의 범위를 줄이고 시장의 역할을 넓히려 했다. 시크는 이를 공산주의와 자본주의 사이의 '제3의 길'로 제시했다. 1968년 4월 부총리 겸 경제장관이 된 그는 둡체크 정부의 경제 개혁을 맡았다. 그러나 바르샤바조약군이 8월 20일 침공하면서 개혁 구상은 실현되지 못했다. 시크는 당시 유고슬라비아에 머물고 있었고, 그해 10월 스위스로 옮겨갔다. 1989년 체코슬로바키아의 공산당 정부가 무너진 뒤 바츨라프 하벨 대통령의 해외 거주 체코인 자문위원회에 참여했지만, 급격한 경제 자유화가 대규모 국영기업을 무너뜨릴 수 있다고 비판했다. 이 입장은 그의 개혁 구상이 단순한 자본주의 전환과 달랐음을 보여준다.$q$ WHERE id = $q$4756$q$;
UPDATE commulingo_person_sections SET body_ko = $q$파벨 아우에르스페르크의 경력은 1968년 개혁 과정 참여에서 친소·친점령 활동으로 방향을 바꾸었다. 체코 외교부 전문 아카이브에 따르면 그는 1965년 체코슬로바키아 공산당 중앙위원회 이념부장이 되었고, 1968년 행동강령 준비에도 참여한 것으로 전해진다. 그러나 이후 개혁 과정에 반대했으며, 1968년 8월 소련 침공 뒤에는 드레스덴에서 점령을 지지하는 체코어 라디오 방송의 편집자로 활동했다.

1969년에는 중앙위원회 국제정치부서의 책임자가 되었고 1974년까지 그 직책을 맡았다. 이어 1986년 여름까지 국제 공산주의 운동을 표방한 잡지 『평화와 사회주의의 문제』의 국제 사무국과 편집위원회에서 체코슬로바키아 공산당을 대표했다. 1986년 8월 네덜란드 대사로 임명되었으나, 8개월 뒤 사망했다. 이 경력은 그가 프라하의 봄기에 개혁 문서 작성에 관여한 인물이면서도, 침공 이후에는 정상화 체제의 당무와 국제 활동을 수행했음을 보여준다.$q$ WHERE id = $q$4805$q$;
UPDATE commulingo_person_sections SET body_ko = $q$스킬링은 1937년 런던대학교에서 박사 논문을 준비하며 처음 체코슬로바키아를 찾았고, 논문 주제는 19세기 보헤미아 지역의 체코인과 독일인의 관계였다. 같은 해 9월 4일 그는 프라하 스트라호프 경기장에서 열린 즈보로프 전투 기념식에 참석해 토마시 가리그 마사리크가 대통령으로서 마지막으로 공개 석상에 나선 자리를 목격했다. 당시 그는 라디오 프라하의 전신인 단파방송 라디오저널의 방송인으로 일했고, NBC와 CBS의 뉴스 방송 업무도 맡았다. 1938년 9월 뮌헨협정이 체결될 때 그는 프라하에 있었고, 이듬해 3월 나치의 체코슬로바키아 점령이 시작될 때도 현지에 남아 있었다. 그는 1939년 4월 프라하를 떠나 나치 지배하의 빈에서 박사 연구를 마쳤다.$q$ WHERE id = $q$3873$q$;
UPDATE commulingo_person_sections SET body_ko = $q$1968년 8월 20일 밤에서 21일 새벽 사이, 바르샤바조약 5개국 군대가 체코슬로바키아에 진입했다. 둡체크와 동료 지도자들은 중앙위원회 청사에서 소련 공수부대에 연행되어 모스크바로 압송되었고, 8월 26일 개혁의 대부분을 되돌리는 모스크바 의정서에 서명해야 했다. 크리겔 한 사람만이 서명을 거부했다. 귀국한 둡체크가 라디오에서 국민에게 연설할 때 그의 목소리는 여러 차례 끊겼다. 1969년 4월 그는 후사크로 교체되었고, 터키 대사를 거쳐 1970년 당에서 제명된 뒤 슬로바키아 산림청의 기계 담당 직원으로 15년을 감시 속에서 일했다.

문서고 개방 이후의 연구는 개입 결정이 블록 붕괴에 대한 공포와 「건전한 세력」을 자처한 체코슬로바키아 보수파의 요청 서한 위에서 내려졌음을 보여주었다. 그러나 개입은 스스로 내건 목적에서도 실패로 판정되었다. 그것은 개혁을 멈춰 세웠으나 사회주의에 대한 대중의 신뢰를 함께 무너뜨렸고, 서유럽의 공산당들을 이반시켰다. 1989년 12월 4일, 개입에 참여했던 바르샤바조약 국가들 스스로가 1968년의 개입을 부당한 내정 간섭으로 공식 규탄했다.

1989년 11월 24일, 둡체크는 프라하 바츨라프 광장이 내려다보이는 발코니에 하벨과 나란히 서서 21년 만에 군중 앞에 모습을 드러냈다. 그해 12월 28일 그는 연방의회 의장으로 선출되었다. 그는 마지막까지 자신을 민주적 사회주의자로 여겼고 1992년 슬로바키아 사회민주당에 합류했으며, 그해 9월의 교통사고 후유증으로 11월 7일 사망했다. 소련에서 자란 소년이 사회주의의 갱신을 시도하고, 그 시도를 짓밟은 결정이 훗날 그 결정의 당사자들에 의해 철회되는 것을 지켜본 생애였다.$q$ WHERE id = $q$235$q$;
UPDATE commulingo_person_sections SET body_ko = $q$얀 파우에르는 1990년부터 1993년까지 체코슬로바키아 정부가 임명한 역사위원회에서 1967~1971년 체코슬로바키아 사건을 조사하는 작업에 참여했다. 파우에르는 이 위원회 활동을 바탕으로 1995년 브레멘에서 『프라하 1968: 바르샤바조약군의 침공』을 출간했는데, 이 책은 1968년 8월 침공에 이르는 경과와 이후 정치적 복고의 첫 시기를 재구성한 연구다. 이 연구가 기존 논의와 구별되는 지점은 사료 기반이다. 파우에르는 체코슬로바키아 각료문서보관소 자료뿐 아니라 소련, 동독, 헝가리, 폴란드 공산당 중앙위원회 문서보관소의 자료를 처음으로 열람했고, 그때까지 학계에 공개되지 않았던 이 사료들에 기초해 1968년 개입의 정치적·군사적 배경과 전개 과정에 대한 새로운 평가를 제시했다. 이 때문에 서평자들은 이 책을 1968년 프라하와 모스크바의 충돌을 다룬 사실상의 표준적 연구로 평가했다. 파우에르 자신은 2011년 유럽기억과연대(ENRS) 기고문에서 이 시기를 어떻게 정리하는지를 밝혔다. 그는 개입에 반대한 소련·폴란드·헝가리·동독의 소수 반체제 세력의 항의를 동유럽 진영 발전의 분기점으로 보았고, 이를 '시민사회 반대운동의 시작이자 개혁공산주의의 역사적 종말'로 규정했다.

그러나 같은 글에서 파우에르는 1968년의 의의가 단순한 종말로 환원되지 않는다고 보았다. 그는 개혁공산주의가 1989년 이후 새로 성립한 민주주의에 이론적·제도적 유산을 남기지 못했다고 인정하면서도, 프라하의 봄의 시민사회적 유산이 1970~80년대 동유럽 시민권 운동의 토대가 되었고, 민주적 자유의 회복이 공산주의 독재를 평화적으로 극복하는 가장 짧은 길임을 확인시켜 주었다고 주장했다. 아울러 파우에르는 1968년이 '두 번 묻혔다는' 당시 체코 지식인들의 문제제기를 소개하며, 1989년 이후 신자유주의 정당들이 프라하의 봄을 정치적으로 활용했다고 비판했다. 이는 개혁파 공산주의자들이 프라하의 봄을 벨벳혁명의 직접적 전조로 보는 단순한 공식과, 인민의 민주주의 요구에 개혁파가 통치 근대화만을 추구했다고 대립시키는 신자유주의적 설명을 모두 거부하는 입장이었다.$q$ WHERE id = $q$4163$q$;
UPDATE commulingo_person_sections SET body_ko = $q$1970년대 정상화 체제가 들어서면서 세이페르트는 시민적 입장과 공적 권위 때문에 새 권력의 미움을 산 작가 대열에 들어가 은둔을 강요당했다. 그의 작품 가운데 일부 재판만이 드물게 나올 수 있었고, 새 작품은 1970년대 말에 이르러서야 유보 조건 아래 공개되었다. 체제는 그가 큰 인기를 누리고 있었기 때문에 그를 어떻게 다룰지 방법을 찾고 있었다. 책을 내주는 대가로 공개 발언과 서명 운동에 나서지 않는다는 합의를 세이페르트는 거듭 어겼고, 1976년 12월에는 차르타 77의 첫 서명자 가운데 한 사람이 되었다.

이 시기 그의 작품은 사미즈다트를 통해 정기적으로 유통되었다. 《시인이 된다는 것》, 《모두병 기둥》, 《세상의 모든 아름다움》 같은 시집이 사미즈다트로 나왔고 사람들은 그것을 필사해 널리 퍼뜨렸다. 사미즈다트 유통은 당국이 처벌하는 행위였다. 이르지 그룬토라트는 세이페르트와 보후슬라프 레이네크의 시집 등을 비롯한 문학 텍스트와 음악 녹음물을 퍼뜨린 혐의로 국가 전복죄로 4년 징역형을 선고받았고, 석방된 뒤에도 3년 동안 이른바 보호관찰 처분을 받아 밤에 프라하 2구를 벗어날 수 없었다. 세이페르트 본인이 투옥된 것은 아니며, 이 사례는 그의 금서가 제3자의 형사처벌로 이어진 별개의 문서화된 사건이다.

정상화 체제의 압력 속에서도 세이페르트는 1984년 노벨 문학상을 받았다. 건강이 나빠 시상식에 참석하지 못해 딸이 대신 상을 받았고, 체제가 통제하는 매체는 이 중대한 사건을 한 줄 언급으로 처리했다. 노벨상 심사에 필요한 자료와 회고록 《세상의 모든 아름다움》 원고를 해외로 보낸 이르지나 시클로바는 그 때문에 사법 처벌까지 받았다. 체제는 최고 권위의 문학상을 부정할 수 없었고, 그를 침묵시키는 대신 사후에 그를 자기 선전에 끌어들이려 했다. 1976년 차르타 77 서명과 사미즈다트 유통, 노벨상 수상은 체코슬로바키아 당국이 문학을 통제하려 한 방식과 그 통제가 끝내 관철되지 못한 지점을 함께 보여준다.$q$ WHERE id = $q$4180$q$;
UPDATE commulingo_person_sections SET body_ko = $q$1966년 말 믈리나르시는 체코슬로바키아 공산당의 정치 개혁 연구팀을 이끌었다. 법률가이자 정치이론가인 그는 기존 체제를 교체하기보다 개혁하는 점진적 노선을 공개적으로 제시했고, 연구팀은 사회집단과 조직의 여론을 조사해 정치 개혁의 개념을 세우고 향후 5~7년간의 논의를 형성하려 했다. 이 연구는 바르샤바조약군 침공 뒤 중단되어 조사 결과를 공개하지 못했다. 1968년 4월 당 행동강령 작성에도 주요 저자로 참여했다.

믈리나르시의 구상은 사회주의 국가의 민주주의를 시민의 권리와 정치적 대표 제도로 발전시키되 공산당의 지도적 역할을 유지하려는 것이었다. 그는 사회주의의 실효적 대표가 공산당 같은 제도를 통해 조직될 수 있다고 보았고, 경제 개혁의 성패가 정치 변화에 달려 있다고 판단했다. 1968년 초 공적 발언에서 민주화를 주로 당내 민주주의와 시민 자유의 법적 보장으로 다루었다. 이처럼 개혁의 범위는 다원주의와 시민 참여를 확대하면서도 당의 선도적 지위를 전제로 했다.$q$ WHERE id = $q$5687$q$;
UPDATE commulingo_person_sections SET body_ko = $q$야쿠봅스키는 1967년 7월 바르샤바조약 연합군 총사령관에 취임한 지 1년도 채 되지 않아 자신의 경력에서 가장 논란이 되는 군사 작전을 맞이했다. 1968년 4월 말, 그는 체코슬로바키아 영토 내에서 바르샤바조약군의 훈련을 준비하기 위해 프라하를 방문했다. 이 방문은 알렉산데르 둡체크의 「인간의 얼굴을 한 사회주의」 개혁에 대해 소련 지도부가 군사적 선택지를 저울질하기 시작한 시점과 겹친다.

야쿠봅스키는 바르샤바조약군 총사령관으로서 「다뉴브 작전」의 군사적 준비를 실무적으로 총괄했다. 1968년 8월 20~21일 밤, 바르샤바조약 5개국(소련, 폴란드, 동독, 헝가리, 불가리아)의 병력 약 25만 명이 체코슬로바키아 국경을 넘었다. 그러나 침공을 불과 며칠 앞두고 소련 지도부는 작전의 현장 지휘권을 야쿠봅스키에게서 육군 총사령관 이반 파블롭스키 대장에게로 넘겼다. 이는 바르샤바조약 연합군 사령부보다는 소련 국방부와 육군 참모본부가 작전 통제의 중심이었음을 보여주는 결정이었다.

야쿠봅스키는 침공 이후에도 1976년 사망할 때까지 바르샤바조약군 총사령관직을 유지하며 동유럽 군사동맹의 재편과 「정상화」 체제의 군사적 뒷받침을 주도했다. 1970년 체코슬로바키아 사회주의 공화국 영웅 훈장을 받았으나, 그가 지휘한 침공은 바르샤바조약의 집단적 군사 개입이 동맹국 주권을 유린한 결정적 사례로 역사에 남았다.$q$ WHERE id = $q$1291$q$;
UPDATE commulingo_history_events SET body_ko = $q$## 1989년의 문턱에서: 제국은 왜 더 이상 버틸 수 없었는가

1989년 5월, 헝가리가 오스트리아와의 국경 철조망을 걷어 내기 직전까지 동유럽은 겉보기에 안정된 소비에트 블록이었다. 폴란드, 동독, 체코슬로바키아, 헝가리, 불가리아, 루마니아 ― 여섯 나라 모두 집권 공산당이 헌법에 명시된 「지도적 역할」을 유지하고 있었고, 바르샤바 조약군 50만 이상이 동유럽 전역에 주둔해 있었으며, 국가보안기관들은 반체제 인사를 감시하고 억압했다. 그러나 그 표면 아래에서는 제국을 떠받치던 세 개의 기둥이 동시에 무너지고 있었다.

첫째, 소련 경제가 붕괴 직전이었다. 1970년대 석유 가격 폭등으로 연명했던 소비에트 체제는 1985-86년 유가가 배럴당 30달러에서 15달러로 반감하자 외화 수입이 급감했다. 경화 부채는 1984년 220억 달러에서 1987년 410억 달러로 두 배 가까이 뛰었고, 1989년에는 부채 상환이 경화 수출의 30%를 잠식하기에 이르렀다. 미하일 고르바초프가 1985년 3월 서기장에 오른 것은 바로 이 정체의 한복판에서였다. 그가 내건 페레스트로이카(재건)와 글라스노스트(개방)는 경제 회생을 위한 것이었으나, 개혁이 깊어질수록 통제는 풀리고 위기는 심화되었다. 1986년 체르노빌 참사는 180억 루블을 삼켰고 체제의 무능을 적나라하게 드러냈다.

둘째, 소련의 경제적 압박은 동유럽 위성국들에 대한 제국의 보조금 체계를 무너뜨렸다. 소련은 코메콘(CMEA) 무역 체계 안에서 동유럽에 값싼 석유와 원자재를 공급해 왔는데, 외화가 필요해지자 석유 수출을 점차 경화 시장으로 돌렸다. 동유럽에 대한 코메콘 경유 석유 수출 비중은 1980년 46%에서 1990년 16%로 추락했다. 동시에 각국은 저마다 깊은 경제난에 빠져 있었다. 폴란드는 390억 달러의 대외 부채와 초인플레이션에 시달렸고, 1988년 봄과 여름 두 차례의 파업이 전국을 휩쓸었다. 헝가리는 200억 달러의 부채를 안고 있었으며, 1988년 5월 32년간 집권한 카다르 야노시가 물러나고 그로스 카로이가 서기장이 되었지만 개혁파와 보수파의 균열은 봉합되지 않았다. 동독은 서방 차관으로 겉보기 안정을 유지했으나 실물 경제는 침체되어 있었다. 루마니아는 니콜라에 차우셰스쿠가 1989년 봄 모든 대외 부채를 상환했다고 선언했지만, 식량 배급과 정전 속에서 국민은 극도의 긴축에 시달리고 있었다.

셋째, 그리고 결정적으로, 소련의 무력 개입을 정당화해 온 이념적 장치가 해체되었다. 1968년 체코슬로바키아 침공을 사후 정당화한 브레즈네프 독트린은 한 사회주의 국가의 체제 위협이 사회주의 공동체 전체의 문제이며 따라서 개입할 권리가 있다는 논리였다. 그러나 고르바초프는 1986년 이후 이 독트린에서 한 발짝씩 물러섰다. 1988년 12월 7일 유엔 총회 연설에서 그는 "선택의 자유는 보편적 원칙이며 여기에는 어떤 예외도 있을 수 없다"고 선언하고, 동시에 동유럽 주둔 병력 50만 명의 일방적 감축을 발표했다. 이 연설이 있기 두 달 전인 10월 31일 회의록에서, 고르바초프는 참모들에게 이 연설이 "새로운 세계 질서"의 윤곽을 그려야 한다고 말했다. 개입은 더 이상 선택지가 아니었다.

동유럽 지도자들의 반응은 셋으로 갈렸다. 폴란드의 보이치에흐 야루젤스키는 1988년 파고가 꺾이지 않자 1989년 1월 당 중앙위원회를 설득해 연대노조와의 원탁회의를 열기로 했고, 2월 6일 협상이 시작되었다. 헝가리에서는 1988년 11월 총리가 된 네메트 미클로시가 개혁파를 이끌며 1989년 1월 "민주주의 패키지"를 의회에서 통과시켰고, 5월 2일 오스트리아 국경 철조망 해체에 착수했다. 이 두 나라는 이미 개혁의 길로 접어들고 있었다. 반면 동독의 에리히 호네커, 불가리아의 토도르 지프코프, 체코슬로바키아의 구스타프 후사크, 루마니아의 차우셰스쿠는 개혁을 완강히 거부했다. 그들이 믿은 것은 두 가지였다: 자신들의 보안 기구가 저항을 진압할 수 있다는 것, 그리고 결정적 순간에 소련이 개입해 줄 것이라는 것. 1988년 말이 되기 전에 그 두 가지 모두 무너져 있었다. 남은 것은 1989년이었다.

## 철조망이 사라진 이유: 예산, 시험, 그리고 고르바초프의 어깨

1988년 가을, 헝가리 국경수비대는 정부에 세 가지 선택지를 올렸다. 오스트리아 국경 240km에 걸친 소비에트제 신호장치(SZ-100)를 현대화하거나, 서방 부품으로 전면 재구축하거나, 철거하는 것이었다. 수비대가 권고한 것은 세 번째였다. 매년 4,000회에 달하는 오경보(토끼·새·취객이 울렸다)와 1백만 달러에 이르는 유지비, 그리고 1988년 초부터 헝가리인들이 이미 합법적으로 서방 여행을 할 수 있게 된 현실 앞에서, 이 장치는 쓸모를 다했기 때문이었다.

1988년 11월, 취임한 지 한 달도 안 된 네메트 미클로시 총리는 12월 예산안에서 신호장치 유지비 항목을 삭제했다. 네메트는 훗날 "국경 당국도 세 번째 안을 지지했다"고 AFP에 말했다. 이 시점에서 결정의 동기는 실용적이었다. 헝가리의 대외부채는 170억 달러에 달했고, 세계은행 추산 인구의 17%가 빈곤 속에 살았다. 수리할 돈이 없었고, 수리할 이유도 희미해지고 있었다.

그러나 네메트는 이것이 단순한 예산 문제가 아님을 잘 알고 있었다. "개혁 국가인 폴란드와 헝가리에게는 구식 정통 공산주의 정권의 기반을 약화시키는 것도 우리의 이익이었다. 이념적 이유도 있었던 것이다." 1989년 3월 3일, 네메트는 모스크바를 방문해 고르바초프에게 여러 현안과 함께 국경 철거 계획을 전달했다. "서부와 남부 국경의 전자·기술 방어 시설을 완전히 제거하기로 결정했습니다. 헝가리인들은 더 이상 국경을 넘지 않으며, 이제는 루마니아와 동독 시민들만 불법 탈출 시도 중에 붙잡힐 뿐입니다." 고르바초프의 답변은 담담했다. 공식 기록에 따르면 "솔직히, 거기서 나는 문제를 보지 않습니다. 우리도 더 개방되고 있습니다." 그리고 덧붙였다. "국경이 경비되는 한, 그것은 당신들의 책임이다."

네메트는 이것을 브레즈네프 독트린의 종언으로 읽었다. 같은 자리에서 고르바초프는 1956년 소련의 헝가리 개입을 언급하며 "내가 이 의자에 앉아 있는 한, 1956년은 결코 다시 일어나지 않을 것"이라고 말했다. 네메트는 비행기 안에서 측근에게 "5년이나 10년 전에 내가 모스크바에서 같은 말을 했다면, 이 비행기는 시베리아로 향했을 것"이라고 말했다.

철거는 비밀리에 시작되었다. 네메트는 체코슬로바키아와 소련군이 지켜보는 곳에서 시작하기 위해 북서부 러이커(Rajka) 지점을 골랐다. 4월 중순까지 3~4km의 철조망이 사라졌다. "핫라인은 울리지 않았고, 소련 대사도 급히 불려 들어오지 않았다." 네메트의 말이다.

1989년 5월 2일, 헝가리 정부는 국경 철거를 공식 발표했다. 그러나 발표 시점에 이미 철조망의 3분의 2는 철거된 뒤였다. 서독 텔레비전이 이 소식을 전 세계에 퍼뜨렸다. 6월 27일, 호른 줄러 헝가리 외무장관과 알로이스 모크 오스트리아 외무장관이 국경에서 볼트 커터로 철조망을 자르는 상징적 의식을 가졌다. 네메트는 훗날 한 가지 문제를 회고했다. "철조망이 남아 있지 않았다. 우리는 철의 장막을 다시 세워야 했다. 물론 진짜는 아니고, 200~300미터짜리 철망을 말이다."

동독은 즉각 반응했다. 에리히 호네커 정권은 헝가리의 배신을 규탄하며 바르샤바 조약 동맹국들에 압력을 가했다. 7월 말 바르샤바 조약 정상회의에서 토도르 지프코프(불가리아), 밀로시 야케시(체코슬로바키아), 니콜라에 차우셰스쿠(루마니아)는 헝가리와 폴란드를 제외한 특별 회의를 요구하며 "마르크스-레닌주의가 이미 파괴된" 이 국가들을 어떻게 '도울' 것인지 논의해야 한다고 주장했다. 네메트에 따르면, 고르바초프는 연설에서 그 불만들을 전혀 언급하지 않았고, 카메라에 포착된 윙크 하나로 네메트에게 모든 것을 말했다.

헝가리의 국경 개방은 철조망의 물리적 제거 이상이었다. 그것은 소련이 더 이상 무력으로 동유럽의 질서를 떠받치지 않을 것이라는, 현장에서 검증된 최초의 증거였다. 네메트는 이렇게 회고했다. "우리는 모스크바의 반응을 시험할 절호의 기회를 가졌다. 우리는 계속했고, 반응은 없었다."

## 65 대 35의 착각: 모두가 틀린 선거

원탁회의가 1989년 4월 5일 타결됐을 때, 폴란드 통일노동자당(PZPR) 지도부는 자신들이 승리했다고 믿었다. 합의문은 460석의 세임(하원) 중 65%, 즉 299석을 당과 그 위성정당(통일인민당, 민주당)에 보장했고, 야당인 연대노조는 35%인 161석만 자유롭게 경쟁할 수 있었다. 100석의 새 상원은 완전 자유선거였지만, 상원은 대통령의 비상권한에 제동을 걸 수 있을 뿐 법안을 막을 수는 없었다. 당 서기장 보이치에흐 야루젤스키는 대통령에 당선되면 군 통수권과 계엄령 선포권을 쥐게 될 것이었다. 그 계산으로는, 연대가 국민의 불만을 배출하는 합법적 통로가 되어 주되, 실권은 여전히 당에 남는 구조였다.

그러나 이 계산은 두 가지를 놓치고 있었다. 첫째, PZPR은 자신들이 얼마나 미움받고 있는지 전혀 알지 못했다. 둘째, 연대는 불과 두 달 만에 전국적 선거 조직을 가동했다. 선거가 4월 합의 직후인 6월 4일로 잡혀 당 지도부는 야당이 미처 선거운동을 준비하지 못할 것이라 보았으나, 아담 미흐니크가 편집장을 맡은 「가제타 비보르차」(선거신문)가 5월 8일 창간돼 첫 호 15만 부가 매진됐다. 전국 본당에서 시민위원회가 결성되어 후보를 냈고, 유명한 포스터(게리 쿠퍼가 연대 배지를 달고 투표용지를 든 「하이 눈, 6월 4일」)는 투표일을 마치 체제와의 결판인 것처럼 그렸다.

투표 방식 자체가 정권의 오만을 드러냈다. 유권자는 찬성할 후보 옆에 표시하는 대신, 반대할 후보의 이름을 줄 긋는 방식을 취해야 했다. 그리고 PZPR은 당 지도부 35명을 '전국명부'에 올려 무경쟁 출마시켰다. 50% 이상 득표만 하면 당선되는 구조였다. 미에치스와프 라코프스키 총리를 비롯한 각료들과 정치국원들이 이 명단에 이름을 올렸다. 연대 지도부조차 '국민들이 그래도 지도자들 이름 정도는 남겨주지 않겠느냐'고 보았다.

6월 4일 투표 결과는 양측 모두를 충격에 빠뜨렸다. 연대는 자유경쟁 세임 161석 중 160석을, 상원 100석 중 92석을 첫 라운드에서 가져갔다. 평균 득표율은 70~80%에 달했다. 그러나 더 큰 충격은 전국명부의 참패였다. 35명 중 50% 문턱을 넘은 후보는 단 두 명(PZPR의 아담 지엘린스키와 통일인민당의 한 후보)뿐이었다. 라코프스키 총리와 내각 대부분이 낙선했다. 어떤 후보는 10%도 얻지 못했다. 유권자들은 투표용지에서 공산당 지도자들의 이름을 하나하나 줄 그어 지워버린 것이다.

연대 진영에는 환호 대신 불안이 찾아왔다. 브로니스와프 게레메크는 '오만의 죄'라고 평했고, 선거 직후 당선된 비톨트 트셰치아코프스키는 '우리의 승리가 두렵다. 소련이 반응할 수 있다'고 말했다. 실제로 6월 6일 폴란드 내무부 산하 부대에 경계강화 명령이 내려졌다. 연대 지도부는 국민들에게 자제를 호소했고, 거리의 축제 분위기는 애써 눌렀다. 미흐니크는 '원탁회의의 대안은 트빌리시와 베이징'이라고 썼다. 1989년 4월 소련군이 트빌리시 시위대를 유혈 진압하고, 바로 6월 4일 천안문에서 중국 인민해방군이 시위대를 향해 총을 쏜 참상이 생생한 경고였다.

문제는 전국명부의 33개 공석이었다. 선거법은 이 상황을 예정하지 않았다. 6월 12일 국가평의회는 연대의 동의를 얻어 법을 개정해 이 의석들을 지역구로 이관했고, 6월 18일 2차 투표에서 PZPR은 대부분을 회수했다. 그러나 심리적 타격은 돌이킬 수 없었다. 크리스천 사이언스 모니터의 윌리엄 이치크슨은 당을 '관료의 껍데기'라 불렀고, 연대 대변인 야누시 오니슈키에비치는 '당 내 강경파의 공황 반응을 두려워했는데, 다행히 승리의 환호가 없었던 것이 오히려 그들을 진정시켰다'고 말했다.

이제 문제는 대통령 선출이었다. 원탁회의의 암묵적 전제는 야루젤스키의 당선이었지만, 6월 선거의 결과로 국민의회(세임과 상원 합동)에서 공산연합은 겨우 두 석 차이의 다수만을 쥐게 되었다. 연대 의원들 중 야루젤스키(1981년 계엄령을 선포한 그 장군)에게 표를 던질 수 있다고 공언한 사람은 아무도 없었다. 존 데이비스 주폴란드 미국 대사는 6월 22일 연대 지도부와의 비공개 만찬에서 성냥갑 뒷면에 숫자를 적어가며 '머릿수 세기'라는 서구식 의회 전략을 가르쳐주었다. 대량 불참으로 공산당 측이 필요한 정족수를 채우게 하고, 참석한 연대 의원들은 기권해 체면을 지키라는 것이었다. 7월 19일, 야루젤스키는 국민의회에서 단 한 표 차이로 대통령에 당선되었다. 찬성 270표, 반대 233표, 기권 34표. 폴란드 공산당 체제는 살아남았지만, 그 한 표는 이미 유령의 맥박에 불과했다.

## 종이 한 장의 실수인가, 통제의 붕괴인가: 1989년 11월 9일

1989년 11월 9일 밤 베를린 장벽이 열린 사건은 흔히 '샤보프스키의 실수'로 기억된다. 그러나 그날의 결정적 순간들은 단순한 말실수 하나로 환원되지 않는다. 이는 경제적 파탄, 관료적 혼선, 서방 매체의 실시간 보도, 그리고 거리에 쏟아져 나온 시민들의 압력이 겹쳐진 복합적 붕괴였다.

11월 9일의 전제는 10월 말~11월 초 동독 지도부가 직면한 이중 압박에서 시작됐다. 체코슬로바키아는 자국 영토를 경유해 서독으로 빠져나가는 동독 시민들의 물결에 견디다 못해 '동독이 자국민 문제를 스스로 해결하라'는 최후통첩을 보냈다. 동시에 국가계획위원회 위원장 게르하르트 쉬러는 정치국에 '1991년이면 국가가 지급불능에 빠진다'고 경고했고, 그 해결책으로 서독에 대출을 요청하면서 국경 통제 완화를 협상 카드로 삼자고 제안했다. 장벽은 더 이상 이념의 상징이 아니라 흥정 가능한 자산이었다.

11월 6일 발표된 여행법 초안은 1년에 30일, 15서독마르크만 환전 허용한다는 내용으로, 거리의 조롱을 샀다. "30일 동안 세계일주를 돈 없이"라는 구호가 시위대 사이에 퍼졌고, 프라하 주서독대사관은 다시 탈출 희망자들로 넘쳐났다. 체코슬로바키아의 압박 속에 11월 4일부터 국경이 재개방되자 불과 며칠 만에 5만 명이 빠져나갔다.

11월 7일 정치국 회의에서 외무장관 오스카르 피셔는 소련 대사에게 '영구 출국 조항만 먼저 시행하겠다'고 통보했다. 이 제한적 계획을 실행하기 위해 내무부와 슈타지에서 파견된 4명의 실무 관료가 초안을 작성했다. 그런데 이들은 '영구 출국만 허용하면 모두가 영구 출국을 신청할 수밖에 없다'는 논리로 사적 여행(왕복) 조항도 함께 넣었다. 동시에 언론 보도 금지 조치를 11월 10일 오전 4시까지 걸어두고, 그사이 지방 사무소와 국경수비대에 시행 지침을 하달할 계획이었다.

이 신중한 계획을 무너뜨린 것은 당 중앙위원회의 개입이었다. 11월 9일 오후, 중앙위 회의 중 흡연 휴식 시간에 정치국 위원 몇 명이 초안을 승인했다. 에곤 크렌츠는 오후 4시경 중앙위원 216명 앞에서 초안을 낭독하며 "어느 쪽으로 하든 잘못된 수가 될 것"이라고 말했지만, 중앙위는 이를 승인했다. 크렌츠는 이때 정부 대변인에게 보도 금지를 해제하라고 지시했다. 이것은 아직 수정 가능한 실수였다. 그러나 이어진 결정은 되돌릴 수 없었다. 크렌츠는 그 초안과 보도자료를 정치국 위원 귄터 샤보프스키에게 건네며 오후 6시 국제 기자회견에서 발표하라고 했다. 샤보프스키는 이 문제에 관한 그 어떤 논의에도 참석하지 않았고, 초안을 읽어볼 시간도 없었다.

샤보프스키의 기자회견은 동독 텔레비전으로 생중계됐다. 이탈리아 ANSA 통신의 리카르도 에르만이 여행법 초안에 관해 묻자, 샤보프스키는 주머니에서 종이를 꺼내 새 규정을 읽기 시작했다. 기자가 "언제부터 발효되는가?"라고 묻자 그는 서류를 훑어보다가, 보도 금지 날짜는 보지 못한 채, "내가 알기로는 즉시, 지체 없이"라고 답했다. 서베를린 횡단도 포함되느냐는 질문에 그는 어깨를 으쓱이며 "그렇다"고 확인했다. 기자회견은 오후 7시에 끝났고, 서독 DPA 통신은 7시 4분 "동독, 국경 개방"이라는 속보를 타전했다.

서독 ARD와 ZDF의 저녁 뉴스는 동독 전역에 수신됐고, 앵커 한스 요아힘 프리드리히스는 "장벽의 문이 활짝 열렸다"고 선언했다. 수만 명의 동베를린 시민이 국경 검문소로 몰려들었다. 보른홀머 슈트라세 검문소의 책임자 하랄트 예거 중령은 상부에 수십 차례 전화했지만, 중앙위 회의가 연장되어 아무도 응답하지 않았다. 인파가 불어나자 예거는 먼저 '더 공격적인' 이들의 여권에 무효 도장을 찍어 사실상 시민권을 박탈하는 방식으로 긴장을 낮추려 했다. 그러나 수천 명이 "샤보프스키가 말했잖아!"라고 외치며 몰려들었고, 발포 명령을 내릴 상부는 어디에도 없었다. 오후 11시 30분, 예거는 스스로 결정했다. "수문을 열어라." 장벽이 무너졌다.

모스크바는 시차 때문에 깊은 잠에 빠져 있었다. 고르바초프는 다음 날 아침 대사 보고를 받고서야 상황을 알았고, "정치가 민중의 의지에 따라야 한다"며 무력 사용을 처음부터 배제했다. 브레즈네프 독트린이 공식적으로 사망한 것은 7월 부쿠레슈티 선언이었지만, 육체로서 죽은 것은 동베를린의 어느 국경수비대 장교가 상부의 명령 없이, 그리고 상부는 그 명령을 내릴 의지도 능력도 없이, 차단봉을 들어 올리던 바로 그 순간이었다.

## 피로 끝난 유일한 1989: 티미쇼아라에서 트르고비슈테까지

루마니아는 1989년 동유럽 혁명 중 유일하게 총성으로 시작해 총살로 끝난 나라였다. 폴란드의 원탁회의도, 동독의 실수로 열린 국경도, 체코슬로바키아의 극장 합의도 이곳에는 없었다. 12월 16일 티미쇼아라에서 헝가리계 개혁교회 목사 퇴케시 라슬로 강제 퇴거에 반대하는 소수의 신도들이 모인 것이 발단이었다. 차우셰스쿠가 이란을 방문 중이던 12월 17일, 당국은 군대까지 동원해 진압에 나섰고 사상자가 발생했다. 그러나 탄압은 오히려 시위를 도시 전체로 확산시켰고, 12월 20일에는 10만 명이 티미쇼아라 오페라 광장을 가득 메웠다.

차우셰스쿠의 대응은 현실 인식의 완전한 실패를 드러냈다. 12월 20일 저녁 귀국 직후 TV 연설에서 그는 티미쇼아라 사태를 '외세의 간섭'과 '루마니아 주권에 대한 외부의 침략'으로 규정했다. 12월 21일 부쿠레슈티에서 10만 명을 동원한 '자발적 지지 집회'를 열고 발코니에서 연설을 시작했지만, 군중 속에서 터져 나온 야유와 고함은 전국에 생중계되었다. 루마니아인들은 독재자가 두려워하는 얼굴을 TV로 목격했다. 그날 밤 부쿠레슈티 시내에서 보안군과 시위대의 충돌로 사상자가 속출했다.

전환점은 12월 22일 아침에 찾아왔다. 국방장관 바실레 밀레아가 의문의 죽음을 맞은 것이다. 차우셰스쿠는 밀레아가 반역을 자백하고 자살했다고 발표했으나, 일선 병사들은 밀레아가 시민 발포 명령을 거부했다가 살해되었다고 믿었다. 이 소식에 군대는 대규모로 혁명 측에 합류했다. 차우셰스쿠가 새 국방장관으로 임명한 빅토르 스턴쿨레스쿠 장군은 표면적으로는 명령을 수락했지만, 곧바로 부대를 막사로 복귀시키고 차우셰스쿠에게 헬리콥터 탈출을 권유했다. 정오 직전 차우셰스쿠 부부는 공산당 중앙위원회 청사 옥상에서 헬리콥터로 도주했고, 군중은 건물을 점령했다.

부부는 트르고비슈테 인근에서 체포되어 육군 부대로 이송되었다. 12월 25일, 국가구국전선(FSN)이 설치한 특별군사법정이 즉결재판을 열었다. 재판 시간은 약 2시간, 실질적인 심리는 1분 44초에 불과했다. 혐의는 제노사이드(집권 기간 6만 4천 명 사망), 국민경제 파괴, 루마니아 국민에 대한 군사행동 집행이었다. 사형이 선고된 직후 차우셰스쿠는 '자유로운 사회주의 루마니아여 영원하라! 역사가 나를 복수할 것이다!'라고 외치며 인터내셔널가를 부르기 시작했고, 세 명의 낙하산병이 AK-47 탄창을 모두 쏟아부었다. 사형집행 영상은 그날 밤 루마니아 TV를 통해 방송되었다.

그러나 유혈 사태는 차우셰스쿠의 도주 후에 더 심각했다. 혁명 전체 사망자 1,104명 중 942명이 12월 22일 이후의 교전에서 발생했다. 새 권력과 TV 방송은 '차우셰스쿠 충성 세력', 이른바 '테러리스트'가 조직적으로 공격하고 있다고 보도했지만, 훗날의 조사는 대부분의 사상자가 오인 사격과 부대 간 오발로 일어난 '아군 사격'이었음을 밝혀냈다. 루마니아 혁명은 동유럽에서 유일하게 지도자가 처형된 혁명이었고, 그 처형 자체가 베를린에서 프라하까지 이어진 평화적 이행의 서사가 결코 완전하지 않았음을 보여준 마지막 장면이었다.

## 1989년이 매듭지은 것, 열어둔 것

1989년은 몇 가지를 돌이킬 수 없게 만들었다. 브레즈네프 독트린은 폐기됐다. 1989년 10월 25일, 소련 외무부 대변인 겐나디 게라시모프는 기자들에게 "우리는 이제 프랭크 시나트라 독트린을 갖게 됐다. 모든 나라가 자기 길을 가기로 결정한다"고 말했다. 이미 폴란드에서는 비공산당 총리가 집권했고, 헝가리는 국경을 열었으며, 동독은 무너지고 있었다. 소련이 개입하지 않겠다는 선언은 결정이라기보다 사실의 승인이었다. 1989년 12월 몰타 정상회담에서 조지 H.W. 부시는 고르바초프에게 "나는 베를린 장벽 위에서 펄쩍 뛰지 않았다"며 소련의 이익을 해치지 않겠다고 약속했다. 그러나 독일 통일의 속도와 NATO 확장 문제는 이미 움트고 있었다.

무엇이 매듭지어지지 않았는가는 30년 넘게 논쟁의 중심에 서 있다. 첫째, NATO 확장 약속 문제다. 고르바초프와 후일 러시아 지도부는 1990년 독일 통일 협상에서 서방이 NATO를 "1인치도 동쪽으로 확장하지 않겠다"고 구두 약속했다고 주장한다. 미국 측은 그런 약속은 동독 영토에만 해당했으며 동유럽 전체에 대한 구속력 있는 합의는 존재하지 않았다고 반박한다. 1999년 폴란드·헝가리·체코의 NATO 가입, 2004년 발트 3국 가입, 그리고 2022년 우크라이나 전쟁으로 이 논쟁은 단순한 역사 해석의 차원을 넘어섰다.

둘째, 경제 전환의 유산이다. 1989년의 해방감은 오래가지 않았다. 동독 주민들은 통일 후 트로이한트 청산기관의 사유화 과정에서 대량 실업을 겪었고, 폴란드와 헝가리의 충격요법식 시장화는 노멘클라투라 출신이 정치 자산을 경제 자본으로 전환하는 창구가 됐다. 불가리아 해체 직후의 한 반체제 포스터가 외친 구호, "불가리아의 백만장자들이여, 에코글라스노스트에 기부하라!"는 거리로 나온 시민들이 체제의 불평등에 분노했지, 추상적 자유만을 갈망한 것이 아님을 보여준다. 이 평등의 약속이 충족되지 못한 좌절감은 2010년대 이후 중동부 유럽에서 반자유주의 포퓰리즘이 부상하는 토양이 됐다.

역사가들 사이에서 논쟁은 계속된다. 가장 근본적인 질문은 이것이다: 1989년은 누구의 혁명이었는가. 티모시 가튼 애시는 원탁회의를 길로틴 대신 1989년의 상징으로 꼽으며 '반혁명적 혁명'이라 불렀다. 블라디미르 티스머네아누는 시민사회와 반체제 지식인의 역할을 강조했다. 다른 쪽에서는 1989년을 엘리트 간 협상에 의한 체제 전환으로 보며, 대중의 힘보다 공산당 내부 개혁파와 구 엘리트의 이해관계가 결정적이었다고 주장한다. 루마니아의 유혈 봉기, 유고슬라비아의 붕괴, 체코슬로바키아의 평화적 분리, 이 상이한 종착역들은 1989년의 물결이 결코 하나의 결말로 수렴하지 않았음을 말해준다.

1989년 여름, 프랜시스 후쿠야마는 「역사의 종언?」을 발표하며 자유민주주의의 최종 승리를 선언했다. 30년 후, 그 물결이 밀어올린 것은 자유민주주의만이 아니었다. 독립국가들의 전쟁, 민족주의의 귀환, 그리고 한때 소비에트 제국의 중심이었던 나라에서 제국의 꿈을 다시 꾸는 지도자가 등장했다. 1989년은 유럽의 분단을 끝냈지만, 그 폐허 위에 무엇을 세울 것인지는 끝내 매듭짓지 못했다.

## 누구의 1989인가: 역사가들이 아직 다투는 것들

35년이 지났지만, 1989년에 관한 거의 모든 큰 주장은 여전히 논쟁 중이다. 혁명이었는가, 누구의 승리였는가, 약속을 지켰는가: 이 질문들에 학계의 답은 하나로 수렴되지 않는다.

첫째 쟁점은 이름 자체다. 영국 역사가 티머시 가튼 애시는 바르샤바·부다페스트·베를린·프라하를 직접 목격한 뒤 '재볼루션(refolution)'이라는 조어를 제안했다. 개혁(reform)과 혁명(revolution)의 합성어로, 체제가 원탁회의를 통해 스스로의 퇴장을 협상했고 루마니아를 제외하면 평화로웠으며 구 노멘클라투라가 신자본가로 재등장한 현실을 포착한 말이다. 반면 블라디미르 티스머네아누는 1989년이 "진정한 세계사적 사건"이며 "역사적 단층을 확립했다"고 주장한다. 이후의 인종 갈등·부패·비자유주의 물결이 "1989년의 관대한 메시지를 훼손하지는 않는다"는 것이다. 이 논쟁은 평가의 기준을 결정하기 때문에 중요하다. 혁명이었다면 새 질서로 평가해야 하고, 재볼루션이었다면 구 엘리트의 생존은 애초에 예정된 것이었다.

둘째 쟁점은 냉전 종식의 공로를 누구에게 돌릴 것인가이다. 미국 대중 담론에서 로널드 레이건은 "공산주의를 무찌른 사나이"로 기념된다. 그러나 국가안보문서보관소 소장 토머스 블랜턴이 기밀 해제 문서를 분석한 결과, 1980년대 미국의 동유럽 정책은 "실질적으로 변하지 않았고" 미국의 평가는 "혁명을 예측하지 못했으며" 미국 문서는 "무슨 일이 일어났는지 설명하는 데 특별히 도움이 되지 않는다." 레이건 자신도 1988년 모스크바 정상회담에서 "고르바초프 씨가 가장 큰 공로를 차지한다"고 말했다. 오늘날 문서 기록이 지지하는 설명은 더 분산되어 있다. 고르바초프의 '신사고', 양국 정상회담이 낮춘 모스크바의 위협 인식, 그리고 연대노조에서 라이프치히 월요 시위대까지 동유럽인들 자신의 행위성이 결합된 결과라는 것이다.

셋째 쟁점은 현재와 직결된다. 1990년 2월 제임스 베이커 미 국무장관은 고르바초프에게 NATO가 "1인치도 동쪽으로 확장하지 않을 것"이라고 말했다. 국가안보문서보관소의 기밀 해제 문서들은 헬무트 콜, 한스디트리히 겐셔, 프랑수아 미테랑, 마거릿 대처, NATO 사무총장 만프레트 뵈르너로부터 유사한 보증이 있었음을 보여준다. 그러나 고르바초프 자신은 2014년 "NATO 확장이라는 주제는 논의된 적이 없다"고 말해 이전 입장과 배치되는 발언을 했다. 이 논쟁은 학문을 넘어섰다. 블라디미르 푸틴은 이 '깨진 약속'을 우크라이나 침공의 핵심 명분으로 삼았다. 문서 기록은 광범위한 구두 보증이 있었으나 구속력 있는 조약은 없었다는 것을 강하게 시사한다.

넷째 쟁점은 1989년이 약속을 지켰는가이다. 프랜시스 후쿠야마는 1989년 여름 '역사의 종언?'에서 공산주의 붕괴가 "서구 자유민주주의의 보편화"를 의미한다고 주장했다. 25년 후 자신이 지나치게 낙관적이었다고 인정했다. 이반 크러스테프와 스티븐 홈스는 『실패한 빛』(2019)에서 1989년 이후의 "서구 모방의 강제"가 수렴이 아니라 분노를 낳았고, 자유주의적 희망이 가장 컸던 폴란드와 헝가리에서 비자유주의적 전환을 촉발했다고 주장한다. 그러나 티스머네아누의 반론도 무게가 있다. 1989년이 일어나지 않았거나 탈선한 유고슬라비아와 루마니아에서는 국가사회주의 탈출이 훨씬 더 비틀거렸다.

일당 독재의 종말, 소비에트 제국의 해체, 유럽 냉전 분할의 소멸: 이것들은 합리적 의심의 여지가 없는 1989년의 성취다. 그러나 누구의 공로인지, 어떤 종류의 변혁이었는지, 누구에게 무엇이 약속되었는지, 그리고 광장을 채웠던 군중을 후속 민주주의가 존중했는지 배신했는지는 여전히 역사가들이 다투는 질문으로 남아 있다.

## 누가 1989년을 배신했는가: 30년 논쟁의 궤적

1989년이 남긴 유산은 하나가 아니었다. 처음에는 프랜시스 후쿠야마가 1989년 여름 발표한 「역사의 종말」 테제가 시대의 상식이 되었다. 자유민주주의가 마지막 이념적 경쟁자를 물리쳤다는 서사는 베를린 장벽 붕괴와 함께 세계를 사로잡았다. 역사가 마틴 말리아는 마르크스주의 자체에 붕괴를 예정한 '유전자 코드'가 내장되어 있다고 보았다.

그러나 이 승리의 서사는 곧 금이 가기 시작했다. 첫 번째 균열은 1989년의 성격 자체를 두고 벌어졌다. 스티븐 코트킨은 『무질서한 사회』(2009)에서 1989년을 시민혁명이 아니라 공산당 엘리트의 내파(implosion)로 규정했다. 모스크바의 지원이 끊기자 스스로 붕괴한 지배계급의 실패라는 것이다. 반면 현장을 목격한 티모시 가튼 애시는 대중의 행위성을 강조하며 개혁과 혁명의 합성어인 '개혁혁명(refolution)'이라는 개념을 제안했다. 블라디미르 티스머네아누는 1989년이 이데올로기 독점에 맞선 시민적 존엄의 승리라고 보았다.

두 번째 균열은 경제적 차원이었다. 폴란드의 레셰크 발체로비치 재무장관이 주도한 '충격요법', 즉 가격 자유화, 급속한 사유화, 국가보조금 폐지는 이 지역의 표준 처방이 되었다. 그러나 사회적 비용은 엄청났다. 1990~91년 폴란드 산업생산은 거의 4분의 1이 증발했고, 동유럽 전역에서 수백만 명이 비효율적이긴 해도 존재했던 사회안전망을 상실했다. 크리스틴 고드시와 미첼 오렌스타인은 『충격의 재고』(2021)에서 체제전환의 승자와 패자를 실증 분석하며, 산업노동자, 여성, 농촌 인구에게 손실이 집중되었음을 보여주었다.

세 번째 균열은 가장 예측 밖이었다. 1989년을 만들었던 바로 그 사람들이 그 질서에 등을 돌렸다. 1989년 소련군 철수를 요구하는 연설로 헝가리 반체제 진영의 영웅이 된 오르반 빅토르는 2010년대에 스스로 '비자유민주주의'라고 부르는 체제를 구축했다. 폴란드에서는 반공 노조 연대가 우파 정당 법과 정의의 지지 기반이 되었다. 1989년의 승리 서사가 간과했던 민족주의와 반공의 어두운 흐름은 21세기의 지배적 정치 세력으로 부활했다.

30주년을 맞았을 때 질문은 뒤집혀 있었다. '1989년은 어떻게 성공했는가'가 아니라 '무엇이 잘못되었는가'였다. 불가리아의 지식인 이바일로 디체프는 일찍이 "억압된 것은 결코 사라지지 않는다. 언젠가 비합리적 형태로 재출현한다"고 경고했다. 역사가 마우고자타 피델리스는 자본주의의 불가피한 승리라는 서사 자체가 신화가 되어 실제 내려진 선택과 실제로 패배한 사람들을 가렸다고 비판했다. 1989년의 그림자는 폭정에서 민주주의로 향하는 직선로가 아니라, 30년이 지난 지금도 끝나지 않은 논쟁의 장임이 드러났다.

## 30년 후의 거울: 1989년은 끝이었는가, 시작이었는가

1989년이 던진 가장 근본적인 질문은 그로부터 30년 이상이 지난 지금, 더 이상 1989년 당시의 언어로 답할 수 없다. 프랜시스 후쿠야마는 1989년 여름 「역사의 종언?」을 발표하며 자유민주주의가 이념적 진화의 종점에 도달했다고 선언했지만, 그로부터 30년 뒤 그가 묘사한 '역사의 종언'이란 실은 '모방의 시대'의 시작이었다는 반론이 동유럽에서 제기되었다. 불가리아 출신 정치학자 이반 크러스테프와 스티븐 홈스는 2019년 저서 『꺼진 빛』에서 이렇게 썼다: "베를린 장벽 붕괴 이후 유럽은 더 이상 공산주의자와 민주주의자로 나뉘지 않았다. 모방하는 자와 모방당하는 자로 나뉘었다."

이 '모방의 명령'은 냉전 승리 서사가 감추었던 비대칭을 드러낸다. 1989년의 구호가 '유럽으로의 귀환'이었을 때, 그 귀환은 동등한 주체의 합류가 아니라 서구 기준에 따른 자기개조를 의미했다. 크러스테프와 홈스에 따르면, 2010년대 헝가리와 폴란드에서 등장한 반자유주의 전환은 이데올로기적 전향이 아니라 심리적 반발, 즉 외국 모델을 복제해야 한다는 '굴욕적 명령'에 대한 감정적 거부에서 비롯되었다. 오르반 빅토르가 유럽연합의 비판을 받을 때마다 "우리 제도는 당신들로부터 복사한 것"이라고 응수하는 것은, 바로 이 모방의 역설을 정치 무기로 삼은 것이다.

또 하나의 30년 후 발견은 인구다. 1989년의 해방 서사는 국경 개방이 가져올 장기적 인구 유출을 예측하지 못했다. 1989년 이후 동유럽에서 2천만 명 이상이 서유럽으로 이주했고, 불가리아와 라트비아는 인구의 20% 이상을 상실했다. 자유의 대가는 단지 경제적 충격만이 아니었으며, '국민 없는 민족국가'라는 역설이 이 지역의 반자유주의 정치에 연료를 제공했다. 오늘날의 동유럽 포퓰리즘은 '1989년의 배신'이라는 서사와 '사라져가는 민족'이라는 공포가 결합한 산물이다.

그렇다면 1989년은 실패했는가? 이 질문 자체가 잘못 설정되어 있다고 티모시 가튼 애시는 말한다. 1989년의 성취는 비교 가능한 기준점이 없을 만큼 근본적이었다. 공산당 일당 독재의 종식, 소련 제국의 평화적 해체, 핵전쟁 위협의 소멸, 이것들은 1989년이 매듭지은 것이다. 그러나 1989년이 열어젖힌 것들, 즉 민족주의, 경제적 불평등, 새로운 형태의 권위주의, 모방의 굴욕은 1989년이 '해결'한 것이 아니라 '출발'시킨 문제들이었다. 역사가 크리스토퍼 비커턴이 '긴 1989년'이라고 부른 이 변환은 달력의 한 장이 아니라 수십 년에 걸친 구조적 재편이었고, 그 파장은 러시아의 2022년 우크라이나 침공이라는 형태로까지 이어졌다.

1789년 프랑스 혁명의 진정한 평가가 30년 후에 불가능했듯, 1989년의 유산도 아직 진행 중이다. 확실한 것은 하나다. 소련의 탱크가 오지 않은 그해, 동유럽 사람들은 더 이상 외부의 명령이 아닌 자신들의 선택으로 역사를 만들기 시작했다. 그 선택의 결과를 판단하는 일은 지금도 현재진행형이다.$q$ WHERE id = $q$revolutions-1989$q$;
UPDATE commulingo_history_events SET body_ko = $q$## 둔화하는 성장과 비대해진 계획: 1962년의 소련 경제

1962년 9월 9일, 프라우다 지면에 하리코프 공학경제연구소의 옙세이 리베르만 교수가 쓴 「계획, 이윤, 상여금」이라는 글이 실렸다. 이 글이 3년 뒤 코시긴 개혁으로 이어질 거대한 논쟁을 열었다는 사실은 널리 알려져 있지만, 정작 그 글이 왜 바로 그 시점에, 프라우다 1면이 아니라 경제면도 아닌 '토론' 란에 실렸는지를 이해하려면 1962년 소련 경제가 서 있던 자리를 들여다봐야 한다.

1950년대 소련 경제는 연평균 10%를 웃도는 산업성장률로 서방을 놀라게 했다. 그러나 1959년 11.4%를 정점으로 성장률은 해마다 내리막을 걸었다. 1960년 9.5%, 1961년 9.1%, 1962년 9.7%로 잠시 반등했으나 1963년 8.5%, 1964년에는 7.1%까지 떨어졌다. 농업은 더 심각했다. 1963년 농업 총생산은 전년 대비 7.5% 감소했고, 소련은 사상 처음으로 해외에서 1,200만 톤 이상의 밀을 사들여야 했다. 1953년부터 1965년 사이 정부는 식량 수입을 위해 3천 톤이 넘는 금을 매각했다.

위기의 뿌리에는 계획 체계 자체의 구조적 피로가 자리 잡고 있었다. 1957년 흐루쇼프가 도입한 소브나르호스(지역경제평의회) 체제는 중앙 부처의 칸막이를 없애고 지역 단위의 종합적 발전을 꾀했지만, 정작 만들어낸 것은 '지역 이기주의'였다. 각 지역이 자체적으로 모든 산업을 두려 하면서 중복 투자가 만연했고, 통일된 기술정책은 사라졌다. 설상가상으로 흐루쇼프는 10년 사이에 무려 여섯 차례나 경제관리 조직을 개편했고, 1962년 11월에는 당 기관마저 산업과 농업으로 분리하는 초강수를 두었다.

기업 차원에서는 '총생산량'(발로바야 프로둑치야)이라는 단일 지표가 모든 것을 지배했다. 톤수, 개수, 루블 총액으로 계획을 채우기만 하면 원가가 얼마나 들든, 제품이 실제로 팔리든 말든 문제되지 않았다. 관리자들은 의도적으로 낮은 계획 목표를 협상한 뒤 이를 '초과 달성'해 상여금을 받았고, 그 결과 기업은 더 무겁고 더 비싼 제품을 생산하는 쪽으로 움직였다. 이른바 '달성기준'(от достигнутого) 계획은 잘한 기업일수록 다음 해 계획이 가중되고 못한 기업은 쉬운 목표를 받는 역설을 낳았다. 1964년 초 기준으로 판매되지 못한 채 재고로 쌓인 섬유·의류·신발의 가치는 20억 루블을 넘어섰고, 미완성 투자에 묶인 자금은 270억 루블, 연간 투자 총액의 75%에 달했다.

소비자도 더는 침묵하지 않았다. 1962년 6월 1일, 정부가 고기와 버터의 소매가를 25~30% 인상하자 노보체르카스크 전기기관차 공장 노동자 1만 3천 명이 파업에 돌입했고, 군대의 발포로 24명이 사망했다. 이 사건은 경제적 실패가 정치적 폭발로 이어질 수 있음을 모스크바에 각인시켰다.

바로 이 무렵, 또 하나의 조용한 변화가 진행 중이었다. 바실리 넴치노프, 레오니트 칸토로비치, 빅토르 노보질로프 같은 수리경제학자들이 선형계획법과 최적화 이론을 계획에 접목하려는 작업을 진척시키고 있었다. 이들의 접근은 노동가치론만으로 가격을 설명하던 정통 마르크스주의 경제학과 충돌했지만, 1965년 세 사람이 레닌상을 공동 수상하면서 '최적 계획' 진영은 제도적 승인을 얻었다. 리베르만의 논문은 바로 이 두 갈래의 압력, 즉 아래로부터의 경제적 파탄과 위로부터의 학문적 재편이 교차하는 지점에서 터져 나온 신호탄이었다.

## 「계획, 이윤, 프리미엄」: 프라우다가 던진 불씨

1962년 9월 9일, 프라우다는 하리코프 공학경제연구소의 별로 알려지지 않은 교수 옙세이 리베르만의 글 「계획, 이윤, 프리미엄」을 실었다. 이 글이 나오기까지는 우연이 아니라 후원이 있었다. 당시 『프라우다』 편집위원이었던 경제학자 알렉세이 루먄체프가 흐루쇼프에게 리베르만을 소개했고, 흐루쇼프가 게재를 승인했다. 루먄체프는 이미 1956년 자신이 주필로 있던 『꼬뮤니스트』에 리베르만의 글을 실은 적이 있었다. 흐루쇼프로서는 1957년 소브나르호스 개편 이후에도 해결되지 않은 경제의 구조적 비효율을 건드릴 '시험 풍선'이 필요했다.

리베르만의 진단은 날카로웠다. 소련 기업들은 수십 개의 지표로 옥죄여져 있으면서도 정작 자신의 진짜 잠재력을 드러낼 유인이 전혀 없었다. 계획은 '기록 기준', 즉 전년도 실적을 바탕으로 짜였기 때문에 금년에 잘하면 내년 계획이 가중됐다. 그래서 기업들은 실력을 숨기고, 낮은 계획을 받아낸 뒤 안전하게 초과달성하는 것이 합리적인 생존 전략이었다. 상여금은 총생산량에 연동돼 있었기 때문에 원가가 얼마든, 제품이 팔리든 말든 '더 많이' 만들기만 하면 됐다. 리베르만은 이렇게 썼다: "열심히 일한 대가로 스스로를 어려운 처지에 빠뜨릴까 봐 두려워하지 않아도 되어야 한다."

그의 처방은 단순하면서도 급진적이었다. 중앙이 기업에 내려주는 의무 지표를 생산량·품목·납기 일정으로 대폭 축소하고, 나머지는 기업이 스스로 계획을 짜게 하라. 대신 장기 고정된 업종별 수익성(자본 대비 이윤) 기준을 마련하고, 이 기준을 충족한 기업의 이윤에서 일정 비율을 단일 상여 재원으로 삼게 하라. 그러면 기업은 계획을 낮추려 애쓰는 대신 자발적으로 잠재력을 드러낼 것이라는 논리였다. 가격·재정·대규모 투자 같은 '기본 지렛대'는 중앙이 계속 쥐고 있으니 계획경제의 골격은 그대로였다.

출판 직후 폭발적인 반응이 이어졌다. 프라우다는 9월 한 달 동안 10편 이상의 반응 기사를 실었다. 항공기 설계자 안토노프는 「모두를 위해, 자신을 위해」에서 기업 책임자에게 더 많은 권한을 달라고 호소했다. 반대도 거셌다. 전 재무장관 아르세니 즈베레프는 기존의 '기업장 펀드'로 충분하며, 기업 평가는 복수의 생산 지표로 해야 한다고 반박했다. 국가계획위원회와 재무부 출신 관료들은 자원 배분의 우선순위를 중앙만이 정할 수 있다고 맞섰다. 1962년 9월 25~26일 과학아카데미 경제연구소의 확대 회의는 리베르만의 구상을 공식적으로 지지하지 않았다. 리베르만은 자신이 몸담은 하리코프 연구소 안에서도 공격을 받았고, 결국 하리코프 대학으로 자리를 옮겨야 했다.

그러나 논쟁은 멈추지 않았다. 수리경제학파의 거두 바실리 넴치노프는 같은 해 9월 21일 프라우다에 기고하여 「계획 과제와 물질적 자극」이라는 제목으로 리베르만을 옹호했다. 넴치노프는 더 나아가 '생산 기금에 대한 지불' 개념, 즉 기업이 보유한 자본에 대해 국가에 이용료를 내는 제도를 제안했다. "기금을 많이 받은 자에게는 계획 수익성을 책정할 때 많은 것을 요구한다"는 논리였다. 이 아이디어는 훗날 개혁의 핵심 요소가 된다. 1962년 11월 『경제의 문제들』은 17명의 학자·행정가가 참여한 대규모 토론회를 지면에 실었고, 논쟁은 1964년까지 이어졌다. 1964년 8월에는 자동화 전문가 V. 트라페즈니코프가 프라우다에 "지령적 규범에 기초한 낡은 경제관리 형태를 버려야 할 시기가 왔다"고 썼고, 이번에는 비판이 잦아들었다. 논쟁의 장이 실험의 장으로 전환되는 순간이었다.

## 같은 지붕, 두 방향: 1965년 9월 전원회의의 결단

흐루쇼프가 물러난 지 11개월 만에 열린 1965년 9월 27일의 중앙위원회 전원회의에서, 총리 코시긴은 「공업 관리의 개선, 계획의 완성, 공업 생산의 경제적 자극 강화에 관하여」라는 무미건조한 제목의 보고를 올렸다. 보고문에서 '개혁'이라는 단어는 네 번 등장했지만, 전원회의가 채택한 공식 결의문에서는 그마저 사라졌다. 그러나 이날 결정된 조치들은 1930년대 스탈린식 계획 체제가 정착된 이래 소련 경제 관리 방식에 가해진 가장 큰 폭의 수정이었다.

개혁안은 진공에서 나오지 않았다. 1964년 12월 말, 코시긴은 국가계획위원회(고스플란) 부의장 아나톨리 코로보프를 위원장으로 하는 작업반을 구성해 개혁 초안을 준비시켰다. 그러나 첫 번째 장애물은 경제 관료가 아니라 정치 지도부 내부에서 나왔다. 1965년 4월, 코시긴은 소브나르호스(지역국민경제회의)를 전면 폐지하고 10개의 연방-공화국 산업부처를 신설하며, 고스플란의 권한을 대폭 강화하는 안을 제시했다. 브레즈네프가 반대했다. 지역 당 기구들이 관리하던 산업 통제권을 각료회의 산하 중앙 부처로 넘기면 소비에트 경제의 3분의 2가 코시긴의 손에 들어간다는 이유였다. 8월 말에야 타협안이 나왔다: 소브나르호스를 폐지하고 부처 체제를 부활시키되, 기업 자체는 연방공화국의 관할로 남기는 절충이었다. 이로써 관리 체계는 형식적으로 중앙집권화되었지만, 부처들은 개별 기업에 대해 신속하고 강제력 있는 결정을 내릴 권한을 사실상 갖지 못하게 되었다.

9월 전원회의와 그 직후인 10월 4일의 중앙위원회·각료회의 합동 결의, 그리고 같은 날 승인된 「사회주의 국영 생산 기업 규정」은 이렇게 탄생한 개혁의 골격을 법제화했다. 핵심은 두 방향으로 요약된다. 하나는 중앙집권적 복원이었다: 1957년 흐루쇼프가 창설한 47개 소브나르호스를 해체하고, 9개의 전연방 산업부처(경공업부, 화학공업부, 라디오공업부 등)와 11개의 연방-공화국 부처를 신설했다. 다른 하나는 분권화였다: 기업에 내려보내는 의무 계획 지표가 30여 개에서 9개로 줄었다. 핵심 지표는 총생산량 대신 '실현된 제품 판매량'(레알리자치야)과 '수익성'(렌타벨노스티), 즉 이윤의 고정자산 대비 비율이었다.

기업은 이윤의 일부로 세 가지 자극 기금을 조성할 수 있게 되었다: 물질적 장려 기금(노동자 상여), 사회문화·주택 기금(복지·주택 건설), 생산발전 기금(설비 투자)이 그것이다. 종래의 상여금이 임금 기금에서 나와 사실상 고정급의 일부였던 것과 달리, 이제 상여금은 기업이 실제로 벌어들인 이윤에 연동되었다. 또한 기업은 고정자산과 운전자본에 대해 일종의 사용료(플라타)를 국가에 납부하게 되어, 유휴 설비를 쌓아두는 것이 재정적으로 불리해졌다. 기업들은 세부 품목과 구색을 스스로 결정하고, 공급자·소비자와 직접 장기 계약을 체결하며, 인원수를 자체적으로 정할 권한도 부여받았다.

그러나 이 이중 설계에는 처음부터 균열이 새겨져 있었다. 가격은 여전히 중앙이 고정했고, '수익성'을 결정하는 투입 비용은 기업이 통제할 수 없는 변수였다. 가장 근본적인 모순은 이 개혁이 기업에 시장적 유인을 주면서도 그 기업들이 활동할 시장, 즉 생산 수단의 도매 시장, 자유로운 가격 체계, 파산 제도를 하나도 창출하지 않았다는 점이었다. 소비에트 경제사가 그리고리 하닌의 냉정한 평가대로, 이 결정들은 '개혁'이라는 이름을 붙이기에는 너무 약했다. 그러나 1965년 가을, 그 누구도 이 결의안들이 향후 5년간 소비에트 경제에 기록적인 성장 수치를 안기리라는 사실을 의심하지 않았다.

## 1968년의 역류: 프라하가 모스크바의 개혁을 멈추다

1968년 1월 체코슬로바키아 공산당 제1서기에 알렉산데르 둡체크가 선출되고, 4월 「행동강령」이 발표되면서 소련 보수파의 불안은 확신으로 바뀌었다. 둡체크의 '인간의 얼굴을 한 사회주의'는 검열 폐지, 여행 자유, 기업 자율성 확대를 약속했고, 그 경제적 설계를 맡은 이가 바로 오타 시크였다. 시크는 1964년 이미 체코슬로바키아 경제개혁의 초안을 작성한 인물로, 그의 구상은 코시긴 개혁보다 훨씬 급진적이었다. 생산수단의 도매시장, 경쟁적 가격체계, 노동자 자주관리, 대외무역의 분권화까지 포함된 이 청사진은 '계획 아래 시장'이라는 코시긴의 프레임을 넘어서는 것이었다.

모스크바 보수파에게 체코슬로바키아 사태는 하나의 증명이었다. 시크를 비롯한 경제개혁론자들이 정치적 자유화의 선봉이 되었다는 사실은 '경제적 분권화 → 정치적 해빙 → 체제 위기'라는 인과의 사슬을 실물로 보여준 셈이었다. 미하일 수슬로프는 이 논리를 정치국에서 반복했고, 니콜라이 포드고르니는 공개적으로 개혁의 정치적 위험성을 거론했다. 코시긴이 1968년 5월 경제협의회에서 "개혁은 스스로를 정당화했으며 더욱 심화되어야 한다"고 역설한 바로 그 달, 소련 지도부는 이미 체코슬로바키아 개입을 논의하기 시작했다.

8월 21일 바르샤바조약군의 체코슬로바키아 진주는 국내 개혁의 운명도 함께 결정했다. 침공 이후 소련 공산당 내에서는 개혁이 제공한 '자율성'이 이념적 이완으로 이어질 수 있다는 주장이 급속히 힘을 얻었다. 이미 개혁의 내재적 모순, 즉 기업이 가격을 올려 손쉽게 이윤을 늘리는 관행, 임금 상승이 생산성 향상을 앞지르는 현상, 투자재원의 만성적 부족이 드러나던 터에, 정치적 논리가 개혁의 기술적 결함을 덮어버렸다. 1969년부터 부처별로 책정되던 경제적 기준치는 사실상 이전의 행정적 지령으로 환원되었고, 기업의 자율적 투자 결정권은 축소되었다.

브레즈네프는 이 국면에서 결정적 이득을 보았다. 1964~1968년에는 경제·외교에서 코시긴에게 주도권을 내주었지만, 체코슬로바키아 문제는 당 중앙위 서기국, 곧 브레즈네프 자신의 관할이었다. 프라하의 봄 진압을 주도하며 그는 당 기구의 실권자로 부상했고, 코시긴의 개혁은 '정치적 신뢰를 상실한 실험'으로 위상이 격하되었다. 코시긴이 1971년 체코슬로바키아의 류보미르 시트로우갈 총리에게 "모든 것이 무너졌다. 개혁은 그것을 원치 않는 자들의 손에 넘어갔다"고 토로한 데는, 경제논리가 지정학적 공포 앞에 굴복한 1968년의 전말이 응축되어 있었다. 개혁은 공식적으로 폐기된 적 없이 서서히 질식했다. 남은 것은 호지라숏이라는 이름뿐인, 본래의 취지를 상실한 절차였다.

## 개혁이 남긴 것, 남기지 못한 것: 평가의 갈림길

코시긴 개혁이 멈춘 시점은 단번에 특정하기 어렵다. 1968년이 보통 분기점으로 지목되지만, 실제 폐기는 점진적인 후퇴의 연속이었다. 1969년 12월 전원회의에서 브레즈네프는 "이윤은 값을 부당하게 올리는 방식으로도 늘릴 수 있다"고 지적했다. 1971년 노동생산성 지표가 의무 과제로 복원됐고, 1972년부터 물질장려기금에 상한선이 설정됐으며, 1973년 기업 자체 자금 건설이 28% 삭감되면서 개혁은 사실상 종료됐다.

8차 5개년 계획(1966~1970)의 성과를 놓고는 해석이 엇갈린다. 이 기간 국민소득은 연평균 7.8% 성장했고, 공업생산은 50% 증가했으며, 1,900여 개 대기업이 준공됐다. 개혁 지지파는 이윤 유인 도입의 성과로 읽는다. 반대파는 일회성 효과로 본다. 기업들이 숨겨두었던 예비를 드러내고 '졸업' 관행이 줄어든 것은 사실이지만, 기르시 하닌의 표현대로 "선반 위의 자원이 바닥으로 흘러내린" 결과에 불과했으며 시스템 효율 자체는 높아지지 않았다는 것이다.

역사가들의 견해는 크게 세 갈래로 나뉜다.

첫째, **"놓친 기회"** 학파다. 개혁은 올바른 방향으로 출발했으나 프라하의 봄이라는 외생적 충격과 보수 관료의 저항 때문에 좌초되었다는 입장이다. 바이바코프는 회고록에서 "기업 기금에서 예산 적자를 메우기 시작하자 멈출 수 없었다"고 술회했는데, 이는 퇴조가 필연이 아니라 선택의 결과였음을 시사한다. 8차 5개년 계획의 높은 성장률은 이 시각의 결정적 근거다. 이윤 유인만으로도 유의미한 변화가 일어났다면, 개혁을 완주했다면 얼마나 더 큰 성과를 냈겠느냐는 것이다.

둘째, **"구조적 불가능"** 학파다. 행정 가격 체제에서 이윤 지표를 도입하는 것은 처음부터 모순이었다는 입장이다. 실제 기업들은 효율 향상 대신 '신제품'을 가장해 가격을 올리고, 이윤 높은 품목으로만 생산을 쏠리게 했으며, 부처와 행정적 흥정을 벌였다. 1966년 상반기 화폐 발행량은 전년 동기의 1.5배로 뛰었고, 1969년 1월 인구 화폐 잔고가 소매·도매 재고를 26.7% 초과했다. 다론 아제몰루와 제임스 로빈슨(『국가는 왜 실패하는가』, 2012)은 계획 가격이 실제 가치와 유리되어 있어 혁신을 측정할 수 없었고, 장려금 산정이 총임금기금에 연동되어 인원 감축 유인이 사라졌다는 점을 근본 원인으로 꼽는다. 이 입장에서는 1968년도, 관료 저항도 부차적이다.

셋째, **"'개혁'이 아니었다"** 학파다. 하닌은 "1965년 9월 결정을 주의 깊게 읽으면 '개혁'이라는 말 자체가 과장"이라고 썼다. 지표는 30개에서 9개로 줄었지만, 그 9개 안에는 총생산량·주요 품목·임금총액·예산 납부액·중앙투자액·신기술 도입·원자재 공급량 등이 그대로 포함되어 있었다. '이윤'이 등장했지만, 이윤이 시장 경쟁이 아니라 행정 명령의 결과인 구조는 바뀌지 않았다. 이 관점에서 8차 5개년 계획의 높은 성장률은 흐루쇼프 시기 말 혼란에서 정상 상태로 회귀한 반등이었다.

이 세 입장은 상호배타적이기보다 강조점의 차이다. 개혁의 내재적 모순을 인정하면서도 외생적 충격을 부정할 수 없고, 한계를 지적하면서도 1966~1970년의 성과를 무시할 수 없다. 분명한 것은, 코시긴 개혁의 잔해 위에서 소련 경제는 1970년대 내내 총요소생산성 마이너스 성장을 경험했고, 이 '정체'의 체험 없이는 1985년 페레스트로이카도 존재하지 않았으리라는 점이다.

## 평가의 전장: 왜 멈췄는가를 둘러싼 다섯 갈래의 해석

코시긴 개혁이 왜 멈췄는가에 관해서는 지금도 역사가들 사이에 합의가 없다. 크게 다섯 가지 해석이 경쟁한다.

첫째는 「정치적 봉쇄」 해석이다. 프라하의 봄(1968년)이 브레즈네프와 정치국 보수파에게 경제개혁은 곧 정치적 해빙이라는 공식을 확신시켰고, 그 결과 개혁은 정치적으로 질식당했다는 것이다. 코시긴 자신이 1971년 체코슬로바키아 총리 시트로우갈에게 한 말, "개혁은 그걸 전혀 원치 않는 자들의 손에 넘어갔다"가 이 해석의 상징적 증거로 쓰인다.

둘째는 「두 조종간」 해석이다. 올세비치와 그레고리는 개혁의 핵심 모순이 하나의 기업에 지령계획과 유사시장이라는 두 개의 이질적 조종간을 동시에 단 데 있다고 보았다. 두 조종간은 서로 충돌했고, 이 충돌은 점점 심화되어 결국 개혁을 거꾸로 돌릴 수밖에 없었다는 것이다. 1969년까지 상품 적자는 절대적으로 변했고, 기업의 이윤은 예산 수입을 잠식했으며, 투자는 인플레이션을 부채질했다.

셋째는 「애초에 개혁이 아니었다」는 해석이다. 경제사가 하닌은 1965년 9월 결정을 '개혁'이라 부르는 것 자체가 과장이며, 지표를 몇 개 줄이고 이윤이라는 단어를 추가했을 뿐 실질적인 제도 변화는 없었다고 평가한다. 하닌의 관점에서는 8차 5개년계획(1966~1970년)의 높은 성장률도 개혁 덕분이 아니라 석유 개발, 일회성 유휴 설비 가동, 그리고 흐루쇼프기 투자의 결실이 늦게 나타난 결과였다. 야신도 이 시기 성장이 개혁보다는 회복 효과와 원자재 호황에서 비롯됐다고 주장한다.

넷째는 「구조적 불가능성」 해석이다. 2024년 노벨경제학상 수상자 아제모을루와 로빈슨은 계획경제에서 가격은 실물 가치와 단절되어 있으므로 혁신의 가치를 측정할 수 없고, 상여금이 총임금기금에 연동된 설계는 기계화·자동화의 유인을 원천 봉쇄했다고 지적한다. 이 관점에서는 개혁의 실패가 정치적 좌절의 문제가 아니라, 정치체제가 시장을 허용할 수 없는 한 애초에 성공할 수 없는 구조의 문제였다.

다섯째는 「개혁이 남긴 유산」을 강조하는 해석이다. 개혁이 공식적으로는 실패했지만, 기업과 노동자 집단에 '우리'라는 이해관계를 처음으로 각인시켰고, 올세비치·그레고리의 표현을 빌면 "중앙집권적 지령계획의 무덤 파는 군대가 이때 이미 형성되기 시작했다." 그것이 훗날 페레스트로이카의 심리적·제도적 토양이 되었다는 것이다.

이 다섯 해석은 상호배타적이지 않다. 대부분의 연구자는 정치, 제도, 구조, 유산을 배합해 설명하지만, 어디에 방점을 찍느냐에 따라 코시긴 개혁은 '마지막 기회'가 되기도 하고 '어차피 불가능했던 실험'이 되기도 한다.

## 놓친 기회인가, 애초에 불가능했던 일인가: 끝나지 않은 논쟁

코시긴 개혁이 멈춘 지 반세기가 지났지만, 그것이 무엇이었는지에 대한 합의는 없다. 루스템 누레예프가 2017년에 엮은 논문집의 제목, 『놓친 기회인가, 마지막 안전밸브인가』가 이 논쟁의 두 극점을 보여준다. 한쪽에서는 개혁이 소련 체제를 붕괴 없이 현대화할 수 있었던 마지막 실질적 기회였다고 본다. 다른 쪽에서는 애초에 작동할 수 없는 모순 덩어리였고, 부분적으로라도 실행되면서 오히려 계획경제의 훼손을 앞당겼다고 본다.

이 틀을 연 것은 유리 골란드와 알렉산드르 네키펠로프의 2010년 논문이다. 그들은 묻는다: 코시긴 개혁은 '놓친 기회'였는가, 아니면 '신기루'였는가? 이 질문은 이후 러시아 경제사학계의 핵심 쟁점이 되었다. 신기루론의 핵심 논거는 가격 체계다. 개혁은 기업에 이윤 동기를 부여했지만, 가격은 여전히 행정적으로 결정됐다. 예브게니 야신은 8차 5개년 계획(1966~1970) 시기의 높은 성장률이 개혁 덕분이 아니라 흐루쇼프 혼란 이후의 안정화 효과, 유리한 대외 조건, 그리고 무엇보다 아직 고갈되지 않은 사마틀로르 유전 같은 외연적 성장 자원 덕분이라고 주장했다. 반면 개혁이 '진짜 기회'였다고 보는 측은 이렇게 반문한다: 개혁이 실패한 것은 설계의 결함 때문이 아니라 정치적 환경 때문이었다. 1968년 프라하의 봄이 없었다면, 브레즈네프가 아닌 코시긴이 우위를 점했다면, 가격 개혁은 1970년대에라도 이어질 수 있었다.

또 하나의 깊은 균열은 개혁이 소련 체제의 수명을 늘렸느냐 줄였느냐다. 율리 오를세비치와 폴 그레고리는 코시긴 개혁이 소련 역사상 처음으로 '국가로부터 분리된 집단적 경제 이익'을 가진 기업이라는 실체를 만들어냈고, 이것이 장기적으로 계획 체제의 무덤을 팠다고 분석한다. 이 관점에서 보면 개혁의 중단이 체제를 구한 것이 아니라, 오히려 반쪽짜리 개혁의 유산(기업의 이기적 행동, 부처 간의 이익 경합, 중앙 통제의 약화)이 체제를 서서히 잠식했다. 이에 맞서 다론 아제모을루와 제임스 로빈슨은 2012년 저서에서 개혁이 정치 체제의 근본적 변화 없이는 성공할 수 없었고, 따라서 '놓친 기회'라는 말 자체가 성립하지 않는다고 주장한다. 독점적 일당 체제 아래에서는 기업의 자율성을 진정으로 보장할 수 없고, 창의적 파괴를 가능하게 할 제도적 조건도 갖춰질 수 없었다는 것이다.

사실관계 차원에서도 합의되지 않은 것이 있다. 대표적인 것이 8차 5개년 계획의 성과 평가다. 공식 통계는 국민소득 연평균 7.8% 성장을 기록했지만, 기르시 하닌의 대체 추계는 이보다 훨씬 낮다. 하닌은 공식 수치가 개혁을 좋게 보이게 하려는 정치적 의도로 부풀려졌다고 본다. 이 주장이 맞다면, 개혁이 단기적으로도 실패했다는 결론이 나온다. 공식 통계를 신뢰하는 연구자들은 최소한 8차 5개년 계획 기간 동안은 개혁이 효과를 냈다고 반박한다.

개혁과 페레스트로이카의 관계도 해석이 갈린다. 고르바초프의 경제 참모들, 특히 1987년 「국영기업법」의 설계자들은 코시긴 개혁의 설계도를 의식적으로 참조했다. 이 점에서 개혁은 단절이 아니라 연속성 속에 있다. 그러나 일부 연구자는 이 연속성을 부정적으로 읽는다: 코시긴 개혁의 실패가 1980년대 후반에 '계획을 손보는' 방식으로는 체제를 살릴 수 없다는 결론을 이미 증명했는데도 고르바초프 팀이 똑같은 길을 다시 걸었다는 것이다.

2024년 노벨 경제학상을 수상한 아제모을루와 로빈슨의 분석이 추가되면서 논쟁은 한 층 더 넓어졌다. 이들은 코시긴 개혁의 실패를 단일 국가의 정책 실패가 아니라, 포용적 제도 없이는 지속적 경제 성장이 불가능하다는 일반 명제의 사례로 읽는다. 그러나 이 주장에 대해 러시아 경제사학계 일각에서는 '제도 결정론'이 지나치게 단순하다는 반론이 나온다. 1965년 시점에서 중국식의 점진적 시장화 경로가 불가능했다고 단정할 수 있느냐는 것이다.

결국 코시긴 개혁을 둘러싼 논쟁은 세 개의 질문으로 수렴된다. 첫째, 개혁은 제대로 설계되었는가? 그렇다면 무엇이 그것을 죽였는가, 그렇지 않다면 무엇이 잘못 설계되었는가? 둘째, 8차 5개년 계획의 성장은 개혁 덕분인가, 아니면 개혁과 무관한 요인들 덕분인가? 셋째, 개혁의 중단은 체제를 구했는가, 아니면 체제의 종말을 앞당겼는가? 반세기가 지나도록 이 질문들에 대한 답은 하나로 모이지 않았다. 그것은 이 개혁이 단순한 경제정책의 일화가 아니라, 계획과 시장, 정치와 경제, 개혁과 체제 수호 사이의 길항이 집약된 사건이기 때문일 것이다.

## 정체기로 가는 길: 개혁 이후 개혁

코시긴 개혁은 공식적으로 폐지된 적이 없다. 1965년 9월 전원회의 결정을 번복하는 문서는 단 한 건도 채택되지 않았다. 개혁은 뒤집히지 않고 서서히 비워졌다. 1972년 물질적 인센티브 기금에 루블 단위 상한선이 설정되고, 1973년 기업 자체 자금 건설 규모가 28% 삭감되면서 개혁의 심장부였던 기업 자율성은 형해화됐다. 한때 30개에서 9개로 줄었던 지령 지표는 하나둘 복원되었고, 1979년 7월 중앙위 결정은 '순수(규범)생산'이라는 새 지표를 도입하며 사실상 개혁 이전 체제로의 복귀를 완성했다. 1980년대 초 기업은 이윤의 42%를 보유했으나 실제 처분권은 8~9%에 불과했다.

그러나 개혁이 남긴 흔적은 깊었다. 가장 분명한 유산은 제8차 5개년 계획(1966~1970)의 실적이다. 국민소득은 연평균 7.8% 성장해 브레즈네프 시대 전체에서 가장 높은 수치를 기록했다. 이 '황금의 5개년'이 개혁 덕분인지, 흐루쇼프 시대에 착수된 대규모 투자 프로젝트의 결실인지, 아니면 석유·가스 수출 호황과 같은 외생적 요인 때문인지는 오늘날까지 경제사학자들 사이에서 합의되지 않은 질문이다. 기르시 하닌은 이 시기 성장의 상당 부분이 '일회성 예비의 동원'(재고 정리, 설비 가동률 상승, 지불 체계 정상화)에서 비롯되었으며, 개혁의 구조적 효과는 미미했다고 보았다.

또 하나 개혁이 확실히 남긴 것은 거시경제적 불균형이다. 소련 국가은행과 재무부의 비밀 문서는 개혁이 초래한 모순을 냉정하게 기록했다. 기업의 임금 지급 능력이 커지면서 1966년 상반기 화폐 발행량은 전년 동기의 1.8배로 뛰었고, 1969년 1월에는 인민의 손에 쥔 현금 잔고가 소매·도매 재고를 26.7%나 초과했다. 개혁 3년 만에 소비재 부족은 상대적 현상에서 절대적 현상으로 전환됐다. 동시에 기업 이윤이 중앙 예산 대신 기업 유보로 흘러가면서 국가 재정은 적자에 빠졌고, 고스플란 의장 니콜라이 바이바코프는 '일시적 차입'으로 시작해 멈출 수 없게 된 기업 기금 유용을 훗날 인정했다. 개혁은 명령경제의 배관을 뜯어냈지만 그 자리에 기능하는 시장을 놓지 못했고, 그 틈으로 돈이 샜다.

코시긴 개혁의 가장 오래 지속된 유산은 아마도 '다음 개혁'에 미친 영향일 것이다. 페레스트로이카기의 경제학자들은 이 실험을 반면교사로 읽었다. 예고르 가이다르는 이 개혁을 '소련 경제 관리 체제를 바꾸기 위한 마지막 진지한 시도'라고 불렀고, 그 실패로부터 가격 자유화 없는 부분 개혁의 무의미함이라는 교훈을 도출했다. 1965년 개혁은 시장 가격도, 사적 소유도, 경쟁도 없는 상태에서 기업에 이윤 동기만 이식하려 했고, 그 결과는 '명령경제의 최악과 시장경제의 최악을 결합한'(하닌) 혼종이었다. 이 교훈은 1980년대 후반 소련 지도부가 부분 개혁에서 전면적 체제 전환으로 밀려간 이유 가운데 하나였다.

동시에 개혁은 역설적인 질문을 남겼다. 중국과 베트남은 비슷한 시기에 기업 자율성 확대로 출발해 점진적으로 시장을 확대하며 계획경제를 탈출했는데, 왜 소련은 그러지 못했는가. 이 질문에 대해 어떤 연구자는 소련의 계획 체계가 너무 완벽하게 제도화되어 있었기 때문이라고 답하고, 또 다른 연구자는 중국과 달리 소련에는 개혁을 밀어붙일 거대한 농촌 잉여 노동력이 없었다고 말한다. 여기에 결정적인 변수 하나가 더해진다. 1968년 프라하의 봄이다. 정치적 자유화가 경제 개혁의 불가피한 귀결이라는 공포를 소련 지도부의 뇌리에 새긴 이 사건은, 개혁의 경제 논리보다 정치 논리가 언제나 앞선다는 시스템의 철칙을 확인시켰다.

오늘날의 합의는 대략 이렇다. 코시긴 개혁은 진지했지만 불완전했고, 부분적 성공을 거두었지만 구조적 모순을 심화시켰으며, 궁극적으로는 개혁의 불가능성을 입증함으로써 훗날 더 급진적인 변화의 당위를 예비했다. 그것이 기회의 창이었는지, 아니면 애초에 열릴 수 없는 문이었는지에 대한 논쟁은, 냉전이 끝나고 소련이 사라진 뒤에도, 러시아와 서구의 연구자들 사이에서 계속되고 있다.

## 정리된 것, 남은 것: 60년 논쟁이 놓인 자리

코시긴 개혁을 둘러싼 60년의 논쟁은 적어도 세 가지를 정리했다. 첫째, 1965년 9월 전원회의에서 채택된 개혁안은 리베르만·넴치노프가 그렸던 그림과 다른 것이었다. 애초의 구상은 장기적·안정적인 규범 아래 기업이 스스로 이윤을 추구하게 하자는 것이었으나, 실제 실행된 것은 매년 재조정되는 부처별 규범, 임금총액에 묶인 유인기금, 그리고 가격개혁 없는 이윤지표였다. 둘째, 개혁의 초기 성과와 후기 역류 사이에 프라하의 봄이 있었지만, 1968년은 원인이라기보다 방아쇠였다. 개혁은 이미 1967년부터 예산 적자, 임금 폭증, 소비재 부족, 건설 중단 증가라는 내부 모순을 노출하고 있었다. 셋째, 개혁의 후퇴는 단순한 정치적 보복이 아니었다. 브레즈네프의 1969년 12월 전원회의 발언, "이윤은 가격 인상과 불필요한 제품 생산 중단으로도 올릴 수 있었다"는 체제가 감당할 수 없었던 상품-화폐 불균형을 직시한 것이었다.

그러나 세 질문은 여전히 열려 있다.

하나는 인과의 방향이다. 프라하의 봄이 없었더라면 개혁은 살아남았을까? 보수파가 개혁을 위험시하게 된 결정적 계기는 체코슬로바키아였지만, 개혁 자체가 이미 초래하고 있던 거시경제적 불균형, 즉 1969년 초 인민의 현금잔고보다 26.7%나 적은 소비재 재고는 독자적인 위기 요인이었다. 이 질문은 현재진행형이다.

둘째는 개혁의 성격 자체에 대한 근본적 이견이다. 하닌의 평결, "명령경제와 시장경제의 모든 최악의 측면을 결합했다"는 기획 자체의 모순을 지적한다. 반면 사프로노프의 분석은 반대 방향에서 "반쪽짜리여서가 아니라, 반쪽짜리인 채로 가기에는 너무 급진적이었다"고 본다. 후자는 개혁이 성공하려면 가격을 놓아주어야 했고, 가격을 놓아주는 것은 노보체르카스크의 기억이 증명하듯 정치적 자살이었다고 주장한다. 이 두 입장은 같은 실패에 대한 정반대의 해석이며, 오늘날까지 어느 쪽도 상대를 결정적으로 논박하지 못했다.

셋째, 가장 오래되고 가장 큰 질문: 놓친 기회인가, 애초에 불가능했던 길인가. 이 물음은 더 이상 코시긴 개혁만의 것이 아니다. 1965년의 실험은 계획과 시장의 접합이 기술적 설계의 문제인지 정치적 조건의 문제인지를 묻는 더 큰 논쟁의 시금석이 되었다. 개혁이 남긴 가장 분명한 유산은 이 질문 자체다.$q$ WHERE id = $q$kosygin-reform$q$;
UPDATE commulingo_history_events SET body_ko = $q$## 사회주의가 승리했다고 선언한 나라의 침체

1968년 1월 5일 알렉산데르 둡체크가 체코슬로바키아 공산당(KSČ) 제1서기로 선출되었을 때, 그가 물려받은 나라는 15년간의 안토닌 노보트니 통치 아래 모든 면에서 막다른 골목에 다다라 있었다.

경제는 이미 1960년대 초반부터 붕괴 직전이었다. 1960년 헌법은 체코슬로바키아를 소련에 이어 사회주의를 달성한 첫 국가로 선언했지만, 같은 해 시작된 제3차 5개년계획(1961~1965)은 지나치게 야심적인 목표와 대외무역의 실패로 1962년 폐기되었다. 1963년 국민소득은 실제로 감소했고(공산권에서 전례 없는 일이었다), 1965년 국민소득은 1960년 대비 불과 1.9% 상승에 그쳤다. 1956~1960년 연평균 6.9% 성장의 3분의 1에도 못 미치는 수치였다. 체코슬로바키아는 전쟁 전까지만 해도 유럽에서 가장 선진화된 공업국 중 하나였으나, 소련식 중앙계획 모형을 이미 산업화된 경제에 무리하게 적용한 결과는 재앙이었다. 1964년 9월 경제학자 오타 시크를 비롯한 개혁파는 노보트니에게 기업의 수익성 평가와 시장 요소의 부분 도입을 골자로 한 '신경제모형'을 수용하도록 강요했으나, 노보트니는 당 기구의 저항을 이유로 개혁의 실질적 이행을 계속 봉쇄했다.

탈스탈린화 또한 동유럽에서 가장 느렸다. 1963년이 되어서야 슬란스키 재판 희생자들의 복권을 검토하기 시작했고, 실제 복권은 1967년까지도 이루어지지 않았다. 1950년대 숙청으로 숙련된 전문가들이 대거 축출되고 정치적으로 충성스럽지만 무능한 간부들로 교체된 결과는 '쟁기질한 밭 같은 도로, 팔리지 않는 제품, 통행할 수 없는 다리'라는 동시대인의 냉소로 요약되었다. 집단화된 농업은 1960년 생산량이 전쟁 전 수준에도 미치지 못했다.

문화 영역에서는 균열이 더 빨리 진행되었다. 1963년 5월 리블리체에서 열린 프란츠 카프카 국제학술회의는 스탈린 시대에 '부르주아 퇴폐주의'로 낙인찍혔던 작가의 복권을 상징했다. 소련만이 유일하게 대표를 보내지 않은 이 회의는 검열 완화의 신호탄이 되었다. 1967년 6월 제4차 체코슬로바키아 작가대회에서는 루드비크 바출리크가 연단에서 "지난 20년 동안 단 하나의 인간적 문제도 해결되지 않았다"고 선언했고, 밀란 쿤데라와 안토닌 림도 당의 문화 통제를 정면으로 거부했다. 노보트니는 바출리크를 당에서 축출하고 『리테라르니 노비니』에 대한 통제권을 문화부로 이관하는 탄압으로 응수했으나, 이는 오히려 개혁파에 대한 지지를 확산시켰다.

슬로바키아 문제는 여기에 민족적 차원을 더했다. 1960년 헌법은 슬로바키아의 자치권을 대폭 축소해 행정부를 해체하고 슬로바키아 민족평의회의 권한을 프라하 중앙정부에 종속시켰다. 노보트니는 공개적으로 반슬로바키아적 발언을 일삼았다. 1963년 슬로바키아 공산당 지도부가 교체되면서 둡체크가 슬로바키아당 제1서기로 부상했고, 그는 체코 중앙집권주의에 맞서 점진적으로 슬로바키아의 이해를 대변하는 정치세력으로 성장했다. 1967년 10월 KSČ 중앙위원회에서 노보트니와 슬로바키아파의 공개 충돌이 발생했고, 노보트니는 레오니트 브레즈네프를 프라하로 불러들여 지지를 구했으나 브레즈네프는 오히려 노보트니에 대한 반대의 규모에 놀라 지지 철회를 권고했다.

12월 중앙위원회에서 시크는 경제 개혁이 정치 개혁 없이는 불가능하다고 직격했다. 고립된 노보트니는 1968년 1월 5일 사임했고, 중앙위원회는 다른 후보들에 대한 합의에 실패한 끝에 절충 인물인 둡체크를 만장일치로 선출했다. 체코인도, 모스크바파도 아닌 슬로바키아 출신의 온건한 당료에게 기대하는 사람은 거의 없었다. 그러나 그가 올라탄 지반은 이미 깊은 균열로 가득 차 있었고, 아래로부터의 압력은 수년째 축적되어 있었다. 문이 열리는 데는 불과 몇 주밖에 걸리지 않았다.

## 노보트니가 무너진 100일

알렉산데르 둡체크가 1968년 1월 5일 체코슬로바키아 공산당 제1서기에 오른 것은 단순한 인사 교체가 아니었다. 14년간 당과 국가를 장악해 온 안토닌 노보트니가 무너지기까지는 약 석 달이 걸렸고, 그 석 달은 체코슬로바키아 사회에 축적된 모든 균열이 한꺼번에 터져 나온 시간이었다.

발단은 1967년 10월 중앙위원회 회의였다. 슬로바키아 공산당 제1서기였던 둡체크와 경제학자 오타 시크가 노보트니의 리더십을 공개적으로 공격했다. 둡체크는 노보트니가 독재자처럼 행동한다고 말했고, 노보트니는 격분해 둡체크를 \"부르주아 민족주의자\"라고 불렀다. 공산당 어휘로는 가장 무거운 비난이었다. 슬로바키아인들은 오랫동안 노보트니의 프라하 중심주의와 슬로바키아 경시에 불만을 품고 있었다. 1960년 헌법이 슬로바키아 자치기관의 권한을 대폭 축소한 이후, 당내 슬로바키아 간부들의 불만은 개혁파 지식인들의 불만과 합류하고 있었다.

바로 그 10월 31일, 프라하 스트라호프 기숙사에서 시작된 학생 시위가 발생했다. 정전으로 촛불을 들고 거리로 나선 학생들을 경찰이 무차별 폭행했다. 이 사건은 이미 폭넓게 비판받고 있던 노보트니에게 결정타였다. 시위를 제대로 처리하지도 못하고 야당 의견만 더 키운 셈이었다.

궁지에 몰린 노보트니는 1967년 12월 소련 공산당 서기장 레오니트 브레즈네프를 비밀리에 프라하로 초청했다. 자신에 대한 반대를 과소평가하고 있던 노보트니는 브레즈네프가 와서 자신의 손을 들어줄 것이라 기대했다. 그러나 브레즈네프는 반대의 규모에 놀랐고, 프라하에 도착해서는 \"이건 너희 일이다(에토 바셰 델로)\"라는 말로 개입을 거부했다. 당시 체코슬로바키아 공산당 상임간부회는 5대 5로 교착 상태였다. 브레즈네프의 중립 선언은 사실상 노보트니에 대한 소련의 지지 철회로 읽혔다.

1968년 1월 4일 밤부터 5일 새벽까지 이어진 중앙위원회 전원회의에서 노보트니는 제1서기직에서 해임되었다. 후임으로 선출된 사람은 둡체크였다. 그는 개혁파와 보수파 모두에게 타협 후보로 보였다. 지방 출신의 무난한 당료, 모스크바에서 교육받은 \"믿을 수 있는 사람\", 브레즈네프가 \"우리 사샤\"라고 부를 만큼 소련에 우호적인 인물이었다. 체코계 후보들은 하나같이 노보트니와의 연관 때문에 낙마했고, 슬로바키아 출신이라는 점이 오히려 둡체크에게 유리하게 작용했다.

노보트니는 대통령직을 3월 22일까지 유지했으나, 둡체크 체제가 즉시 움직이기 시작했다. 제1서기 취임 직후 둡체크는 \"예술과 과학의 창조성을 질식시키는 모든 것을 제거할 것\"이라고 선언했고, 상임간부회는 개혁 입법을 위한 작업팀들을 가동시켰다. 둡체크 자신도 몰랐지만, 노보트니가 권력 유지를 위해 군 일부 동원을 시도했다는 의혹이 곧 언론을 통해 폭로되면서 노보트니의 대통령직도 무너졌다. 1월 5일의 투표는 한 인물의 교체가 아니라, 20년간 누적된 체코슬로바키아 사회의 모순이 당 내부에서 폭발한 순간이었다.

## 당이 더 이상 '만능 보호자'가 아닌 사회

1968년 4월 5일, 체코슬로바키아 공산당(KSČ) 중앙위원회 전원회의는 63쪽 분량의 「행동강령」(Akční program KSČ)을 채택했다. 프라하의 봄을 문서 하나로 규정해야 한다면 바로 이 강령이다. 초안 작성은 철학자 라도반 리흐타, '인간의 얼굴을 한 사회주의'라는 표현을 처음 고안한 사람, 경제학자 오타 시크, 그리고 파벨 아우에르스페르크가 주도했다.

강령이 내건 조항들은 오늘날의 기준으로 보아도 파격적이었다. 검열의 법적 폐지, 표현·집회·이동의 자유 보장, 비밀경찰(StB) 권한 축소, 1950년대 정치 재판 희생자들의 완전한 복권, 체코와 슬로바키아의 연방제 전환, 그리고 새 헌법 제정을 통한 입법·사법·행정의 삼권 분립이 그 골자였다. 경제 부문에서는 기업의 중앙 지시로부터의 자율성 확대, 시장 메커니즘의 부분적 도입, 노동자 평의회 실험이 제안되었다.

그러나 강령의 진짜 파열음은 정치 체제 개편 구상에 있었다. 문서는 "당의 목표는 사회의 만능 보호자가 되는 것이 아니다"라고 선언하고, 당이 국가 기관과 경제 기관, 사회 조직의 업무를 대신 수행해온 관행을 '유해한 독점적 권력 집중'이라고 비판했다. 당의 지도적 역할 자체를 부정하지는 않았으나, 이 점이 후일 소련 지도부에게 '반혁명'으로 규정될 빌미를 남겼다. 그 역할은 지령이 아니라 설득과 개인적 모범으로 획득되어야 한다고 명시했다. 당원이라도 양심에 따라 행동하고 기능자를 반대할 권리가 있으며, 소수파를 박해해서는 안 된다고 적었다. 국가보안법 231조에 따라 유죄 판결을 받은 정치범들의 모임 '클럽 231'과 무당파 정치 클럽 KAN이 합법화된 것은 이 원칙의 직접적 결과였다.

강령은 경제적 곤경에 대한 냉철한 진단에서 출발했다. 1963년 체코슬로바키아 경제는 마이너스 성장을 기록했고, 1960년대 중반까지도 제자리걸음이었다. 문서는 원인을 '지령-행정적 관리 방식의 유지'에서 찾았고, 노동력과 원자재의 과도한 투입에 의존하는 '외연적 발전'이 한계에 도달했다고 분석했다. 시크의 구상이 반영된 경제 개혁은 기업에 투자·임금·가격 결정권을 넘기고, '과학기술 혁명'에 대비해 자격을 갖춘 전문 간부를 등용하라고 요구했다.

4월 전원회의는 강령 채택과 동시에 대대적인 인사를 단행했다. 4월 8일 올드르지흐 체르니크가 총리로, 시크가 경제 개혁을 총괄하는 부총리로 임명되었다. 4월 18일에는 1950년대 정치 재판의 희생자였던 요세프 스므르콥스키가 국민의회 의장으로 선출되었고, 역시 탄압을 겪은 요세프 파벨이 내무장관에 올랐다. 노보트니 시절 구각(舊閣) 인사들은 대거 물러났다.

모스크바는 강령이 발표되기 전부터 경계하고 있었다. 3월 23일 드레스덴에서 열린 6개국 공산당 정상회담에서 브와디스와프 고무우카와 발터 울브리히트는 체코슬로바키아의 상황을 '기어드는 반혁명'으로 규정했다. 하지만 「행동강령」의 실제 내용은 이보다 더 심각한 문제를 제기했다. 그것은 바르샤바조약 탈퇴도, 자본주의 복귀도 아닌, 공산당의 통치 방식 자체를 근본적으로 재정의하는 문서였다. 소련 지도부에게 이것이야말로 가장 위험한 선례였다.

## 8월 20일 밤: 「블타바-666」, 그리고 하늘과 땅에서 동시에

1968년 8월 20일 밤 10시 15분, 소련군 통신망에 암호신호 「블타바-666」이 흘렀다. 바르샤바조약 5개국에서 25만 명의 병력과 2천 대의 전차가 18개 지점에서 동시에 체코슬로바키아 국경을 넘기 시작했다. 작전명은 「다뉴브」. 제2차 세계대전 이후 유럽 최대 규모의 군사작전이었다.

가장 극적인 장면은 프라하의 루지네 국제공항에서 연출됐다. 국경 돌파와 동시에, 모스크바발 「민간 여객기」 한 대가 프라하 상공에 나타나 엔진 고장을 이유로 비상착륙 허가를 요청했다. 착륙하자마자 100여 명의 사복 차림 GRU 특수부대원들이 기관단총을 꺼내 관제탑과 터미널을 단숨에 장악했다. 곧이어 An-12 수송기들이 1분 간격으로 착륙하기 시작했고, 제7근위공수사단 병력이 경전차와 포를 실어나르며 프라하 시내로 쏟아져 들어갔다.

침공군의 모든 장비에는 흰색 식별 띠가 칠해져 있었다. 흰 띠 없는 차량과 전차는, 그것이 체코슬로바키아 인민군 소속이라 해도, 「무력화」하라는 명령이 사전에 하달되어 있었다. 병력은 소련 17만, 폴란드 4만, 헝가리 1만 2,500, 불가리아 2,164명으로 구성됐다. 동독군은 당초 편성되었으나 침공 직전 모스크바가 돌연 제외했다: 30년 전 독일 점령의 기억이 체코인의 저항을 격화시킬 것을 우려한 조치였다. 루마니아와 알바니아는 참여를 거부했고, 알바니아는 한 달 뒤 바르샤바조약기구에서 탈퇴했다.

바로 그 시간, 프라하 중앙위원회 건물에서는 공산당 간부회가 열리고 있었다. 밤 11시 30분경, 올드르지흐 체르니크 총리에게 마르틴 드주르 국방장관으로부터 전화가 걸려왔다: 「소련군과 4개 동맹국 군대가 국경을 넘고 있습니다.」 드주르 자신은 이미 국방부 건물에서 소련군에 의해 신병이 확보된 상태였다. 충격 속에서도 간부회는 대국민 성명을 작성했다: 「이 침공은 체코슬로바키아 국가기관의 인지도 동의도 없이 자행되었다.」 표결 결과는 7대 4. 반대표를 던진 넷(바실 빌랴크, 드라호미르 콜데르, 올드르지흐 슈베스트카, 에밀 리고)은 바로 그 「건전한 세력」, 즉 수주 전 모스크바에 비밀 서한을 보내 「형제적 원조」를 요청한 자들이었다. 모스크바의 계산은 간부회 내 「건전파」가 6대 5로 우세할 것이라는 예측에 기초했으나, 얀 필레르와 프란티셰크 바르비레크가 막판에 둡체크 편으로 돌아서며 틀어졌다.

새벽 4시 30분, 소련 공수부대가 중앙위원회 건물을 포위했다. 전화선이 절단되고 기관총이 복도를 장악했다. KGB 장교가 둡체크, 체르니크, 요세프 스므르콥스키, 요세프 슈파체크, 프란티셰크 크리겔을 체포했다. 오전 10시, 이들은(KGB와 협력한 체코슬로바키아 내무차관 빌리암 샬고비치의 주도 아래) 소련 장갑차에 실려 루지네 공항으로 이송된 뒤 모스크바로 압송됐다.

체코슬로바키아 인민군은 저항하지 말라는 명령을 받았다. 루드비크 스보보다 대통령은 유혈사태를 막기 위해 무저항을 택했고, 체코인과 슬로바키아인은 거리로 쏟아져 나와 무기를 들지 않은 채 저항했다. 도로 표지판이 사라졌고, 상점에서는 프라하 지도가 치워졌다: 소련군은 구식 제2차 세계대전 지도에 의존해 길을 찾아야 했다. 침공군에 물과 식량, 연료를 제공하는 사람은 아무도 없었다. 그럼에도 충돌은 벌어졌다. 체코 역사학자 프로코프 토메크와 이보 페이초흐의 2017년 연구에 따르면, 침공 첫날에만 50명 이상이 사살당했고, 개입 기간 전체로는 체코인과 슬로바키아인 137명이 사망하고 500명 이상이 부상했다. 소련군 사망자는 96명이었으나, 그중 84명은 교통사고 등 비전투 원인이었다.

8월 21일 하루 만에 바르샤바조약군 24개 사단이 체코슬로바키아 전역의 주요 거점을 장악했다. 체코슬로바키아 라디오 방송국들은 점거되기 직전까지 침공 규탄 성명을 송출했고, 시민들은 탱크 앞에서 소련 병사들에게 러시아어로 「당신들은 왜 우리에게 총을 겨누는가」라고 물었다. 기계적으로는 완벽했지만 정치적으로는 완전히 실패한 작전이었다: 「형제적 원조」를 요청한 정부는 끝내 나타나지 않았다.

## 당원 50만 명을 심사한 체제의 제2막

1969년 4월 17일, 알렉산데르 둡체크가 제1서기에서 물러나고 구스타프 후사크가 그 자리를 차지했다. 후사크 자신도 1950년대에 '부르주아 민족주의자'로 몰려 10년간 수감된 전력이 있는 인물이었기에, 일부는 그가 개혁의 일부라도 지킬 것이라 기대했다. 그러나 후사크는 스스로를 '정상화'가 아니라 '공고화'의 집행자로 규정하며, 모스크바가 요구한 대로 움직였다. 그가 집권한 지 일주일 만에 당과 언론, 사법, 사회단체의 개혁파에 대한 대대적인 숙청이 시작되었다.

숙청의 핵심 기제는 '당원증 교환'이었다. 1970년 2월 『루데 프라보』에 게재된 중앙위원회 서한에 따라, 150만 명이 넘는 전 당원이 특별 심사위원회 앞에 차례로 불려 나갔다. 16만 5천 명의 '건전한 당원'으로 구성된 이 위원회는 면담을 통해 당원 한 사람 한 사람에게 1968년을 어떻게 평가하는지 물었다. '반혁명'이라고 답하지 못한 자, 소련의 개입을 '형제적 원조'가 아닌 '점령'이라고 부른 자, 프라하의 봄 당시 개혁에 가담한 자는 당원증을 반납해야 했다. 1970~71년 사이 1,508,326명이 이 심사를 거쳤고, 326,817명(약 22%)이 당에서 제명되었다. 일부 자료는 최종적으로 약 50만 명이 당을 떠났다고 집계한다. 1968년 1월 170만 명이던 당원 수의 3분의 1 가까이 사라진 셈이다.

숙청은 당에만 머물지 않았다. 중앙위원회 115명 중 54명이 교체되었고, 개혁파였던 올드르지흐 체르니크 총리는 1970년 1월 루보미르 슈트로우갈로 교체되었다. 국민의회 의장이자 대중적 인기가 가장 높았던 개혁파 요세프 스므르콥스키도 직위를 잃고 당에서 쫓겨났다. 둡체크는 1969년 가을 정치국에서 제외된 뒤 1970년 1월 튀르키예 대사로 발령되었으나, 그해 6월 27일 당에서 제명되고 슬로바키아 산림청의 하급 직원으로 밀려났다. 체코슬로바키아 언론인협회는 회원의 절반을 잃었고, 당 기관지 『루데 프라보』는 80명 중 45명이 해고되었다.

1970년 12월 11일, 당 중앙위원회는 바실 빌랴크가 주도해 기초한 「위기 발전의 교훈」을 승인했다. 이 문서는 1968년을 '반혁명'으로 공식 규정하고, 개혁파를 '우익 기회주의자와 반사회주의 세력'으로 낙인찍었으며, 8월의 침공을 '국제주의적 원조'로 재정의했다. 이 텍스트는 단순한 당 문건이 아니었다. 학교 교재로 10만 부씩 다섯 차례나 찍혀 나갔고, 모든 직장에서 학습 대상이 되었으며, 이 언어를 받아들이지 않는 자는 취업, 진학, 출판에서 배제되었다. 1971년 5월 제14차 당 대회에서 후사크는 '정상화가 완료되었다'고 선언했다. 1968년의 봄은 문서상으로도, 일상의 언어로도, 완전히 지워졌다.

## 개혁공산주의는 살아남을 수 있었는가: 지금도 끝나지 않은 해석의 싸움

프라하의 봄이 남긴 유일한 제도적 유산은 연방제뿐이었다는 데는 이견의 여지가 거의 없다. 1969년 1월 1일 발효된 체코사회주의공화국과 슬로바키아사회주의공화국으로의 분할은 개혁이 낳은 수백 개의 조치 중 유일하게 후사크 체제가 폐기하지 않은 것이었다. 언론자유와 여행의 자유는 복구되었고, 비밀경찰의 권한은 회복되었으며, 둡체크가 해임된 1969년 4월 이후 약 50만 명의 당원이 당적을 잃었다. 공산당 내에서 이루어진 개혁은 공산당에 의해 완전히 되돌려졌다.

그러나 그 실패가 '개혁공산주의란 애초에 불가능했다'는 명제를 입증했는지는 50년 넘게 논쟁의 대상이다. 이 논쟁의 가장 선명한 원형은 1968년 12월, 침공 4개월 뒤 두 체코 지식인이 주고받은 글로 이미 출현했다. 소설가 밀란 쿤데라는 『체코의 운명』이라는 글에서 "체코슬로바키아의 가을의 의미는 봄 자체의 의미를 넘어선다"고 주장했다: 비록 짓밟혔지만, 동방의 스탈린주의와 서방의 자본주의 너머에서 사회주의와 민주주의를 결합하려 한 시도는 유럽 전체에 보편적 의의를 지닌다는 것이었다. 극작가 바츨라프 하벨은 『체코의 운명?』이라는 물음표가 붙은 답문으로 응수했다. 프라하의 봄이 회복한 검열 철폐와 기본적 자유들은 "대부분의 문명국에서는 당연한 것"에 불과하며, 이를 두고 체코인이 세계사의 중심에 섰다고 자부하는 것은 "우월감에 빠진 지방적 메시아니즘"일 뿐이라는 냉정한 반박이었다.

이 두 입장은 이후의 모든 해석이 출발하는 좌표가 되었다. 1989년 공산정권이 무너진 뒤 체코에서 보수 진영은 프라하의 봄을 '공산주의자들 간의 권력투쟁'으로 폄하했고, 실패 자체야말로 공산체제의 개혁 가능성이라는 환상이 죽은 역사적 순간이라고 평가했다. 반면 1968년의 주역들이었던 카렐 코시크, 이르지 펠리칸, 에두아르트 골트슈튀커 등은 1989년 이후의 자유주의 정권이 후사크 체제와 다를 바 없이 프라하의 봄을 '두 번째로 매장했다'고 비판했다. 독일의 역사가 얀 파우에르는 이 논쟁을 정리하면서 "개혁공산주의가 '벨벳 혁명'의 직접적 전사였다는 주장도, 인민은 민주주의를 원했는데 개혁공산주의자들은 자기 지배의 현대화만 꾀했다는 신자유주의적 설명도, 둘 다 옳지 않다"고 썼다.

또 하나의 첨예한 쟁점은 프라하의 봄이 소련 진영 전체에 미친 장기적 영향이다. 바르샤바조약군의 궤도가 멈춘 그날, 개혁공산주의는 역사적 가능성으로서 끝났다. 그러나 그와 동시에 소련의 지배에 대항하는 시민사회적 반대운동이 태동했다. 소련, 폴란드, 헝가리, 동독에서 소수의 무력한 반체제 인사들이 침공에 항의한 그 순간은, 동구권에서 당이 아닌 사회가 스스로 조직되기 시작한 출발점으로 평가된다. 프라하의 봄이 진압되지 않았다면 브레즈네프 독트린도 선언되지 않았을 것이고, 1979년 아프가니스탄 침공의 교리적 근거도 존재하지 않았을 것이다. 모스크바가 '사회주의 진영 어느 나라에서든 사회주의가 위협받으면 개입할 권리가 있다'고 명시한 그 독트린은, 1989년 고르바초프가 이를 폐기하고 동유럽의 평화적 이반을 용인할 때까지 소련 외교정책의 공식 원칙으로 남았다.

그리고 프라하의 봄을 진압한 그 연방제만은, 역설적이게도 1993년 체코와 슬로바키아가 평화롭게 분리되는 제도적 틀이 되었다. 개혁이 남긴 유일한 제도는 그 개혁이 지키려 했던 국가 자체의 해체를 위한 발판이었던 셈이다. 역사가들이 오늘날까지 합의하지 못하는 지점은 바로 여기에 있다: 프라하의 봄은 개혁공산주의의 종점인가, 아니면, 1977년 하벨과 68년 세대가 주축이 된 '헌장 77'을 거쳐 1989년의 비폭력 혁명으로 이어지는, 시민사회의 시발점인가.

## 1968년이 확정한 것, 끝내 확정하지 못한 것

프라하의 봄은 적어도 네 가지를 확정했다.

첫째, 소련 지도부가 동유럽에서 감내할 수 있는 개혁의 상한선이 어디인지였다. 1968년 이전까지는 헝가리 1956년의 교훈, 즉 무장봉기만 아니라면 일부 자유화도 가능하지 않은가라는 모호한 질문이 남아 있었다. 프라하의 봄은 이 질문에 답했다. 무장봉기는커녕 당이 스스로 주도하는 합법적·평화적 개혁조차, 검열 폐지와 사회민주당 재건 논의처럼 당의 독점적 지도권을 근본적으로 약화시키는 방향으로 흐르면 소련은 군사력을 동원해 멈춰 세운다는 사실을 입증했다. 이 상한선은 브레즈네프 독트린이라는 이름으로 1968년 11월 공식화되었고, 1979년 아프가니스탄 침공의 논리로도 재활용되었다.

둘째, 국제공산주의운동의 단일한 지도라는 관념이 치명타를 입었다. 1968년 8월 21일 차우셰스쿠가 부쿠레슈티에서 행한 공개 연설은 바르샤바조약 회원국 정상이 소련의 군사행동을 공식 규탄한 최초의 사례였다. 이탈리아 공산당(PCI)은 1969년 모스크바 국제회의에서 최종 결의문 서명을 거부했고, 스페인 공산당과 함께 유로코뮤니즘으로 향하는 길을 열었다. 알바니아는 1968년 9월 바르샤바조약기구를 공식 탈퇴했다. 중소분쟁은 이 사건으로 더 이상 봉합될 수 없는 지경에 이르렀다. 저우언라이는 8월 23일 베이징에서 소련을 '사회제국주의'라 규정했다. 모스크바가 하나의 중심이라는 환상은 1968년에 끝났다.

셋째, 소련 체제의 본질에 대한 서구 좌파의 인식이 돌이킬 수 없이 바뀌었다. 장폴 사르트르와 버트런드 러셀은 침공을 '모스크바의 베트남'이라 불렀다. 얀 파우에르의 표현을 빌리면, 프라하의 봄은 '시민사회적 반대운동의 출발점이자 개혁공산주의의 역사적 종말'이었다.

넷째, 연방제라는 제도적 유산만이 유일하게 살아남았다. 1969년 1월 1일 체코슬로바키아는 체코사회주의공화국과 슬로바키아사회주의공화국으로 구성된 연방제로 전환했고, 이 구조는 1989년 이후까지 지속되어 1993년 평화적 분리의 제도적 틀이 되었다.

그러나 프라하의 봄이 확정하지 못한 것도 적지 않다.

가장 큰 미결 과제는 '개혁공산주의는 처음부터 불가능했는가, 아니면 외부의 무력으로 저지된 실현 가능한 프로젝트였는가'라는 질문이다. 고든 스킬링은 『중단된 혁명』(1976)에서 프라하의 봄을 외부에서 강제로 차단된 실행 가능한 민주적 사회주의 실험이라 보았다. 반면 블라디미르 티스머네아누는 『1968년의 약속들』(2011)에서 개혁공산주의자들의 자기이해 자체가 환상이었다고 평가한다. 당의 지도적 역할을 유지하면서 검열을 폐지하고 복수정당제를 논의하는 것은 내적 모순이라는 것이다. 이 논쟁은 1989년 이후 체코 내에서 더 복잡해졌다. 파우에르에 따르면, 1990년대 초 체코의 신자유주의적 정치 엘리트들은 프라하의 봄을 '공산당 내부의 권력투쟁'으로 격하했고, 개혁파 지식인들은 자신들이 후사크 체제와 1989년 이후 체제 양쪽에 의해 '두 번 매장되었다'고 반박했다. 여론조사에서 프라하의 봄은 체코 시민 다수에게 민주주의 회복 시도로 각인되어 있지만, 그 의미를 둘러싼 다툼은 끝나지 않았다.

두 번째 미결 과제는 소련의 개입 결정이 언제 내려졌는가다. 1968년 3월 드레스덴 회의 시점인지, 7월 체르나 협상 결렬 이후인지, 아니면 보수파의 '초청장'이 명분을 제공한 8월인지에 대해서는 아직도 기록이 완전히 열리지 않아 논쟁이 계속된다. 키런 윌리엄스는 『프라하의 봄과 그 이후』(1997)에서 개입 결정이 점진적으로 형성되었으며, 브레즈네프 자신도 7월 말까지 최종 결정을 유보했다는 견해를 제시했다.

결국 프라하의 봄이 확정한 것은 동유럽에서 소련식 사회주의가 평화적으로 변형될 수 없다는 사실이었고, 확정하지 못한 것은 그 변형의 시도 자체가 역사적으로 유효한가라는 질문이다. 1989년 고르바초프가 브레즈네프 독트린을 폐기했을 때, 외교부 대변인이 페레스트로이카와 프라하의 봄의 차이를 묻는 질문에 답한 '19년'이라는 말은 그 시간의 무게를 정확히 가리켰다.

## 두 번 묻힌 봄: 1968년을 둘러싼 기억의 전쟁

프라하의 봄이 끝난 방식은 역사적 평가 자체를 사건의 일부로 만들었다. 바르샤바조약군이 철수한 뒤에도, 1989년 체제가 무너진 뒤에도 1968년의 의미는 합의되지 않았다. 오히려 두 차례의 체제 전환, 즉 1969년의 '정상화'와 1989년의 민주화는 각각 프라하의 봄에 대한 상반된 공식 기억을 생산했다.

후사크 정권은 1970년 「위기 발전의 교훈」을 통해 1968년을 '반혁명'으로 규정했다. 이 교리는 50만 당원을 숙청하고 개혁파를 공적 기억에서 삭제하는 작업의 토대였다. 바실 빌랴크가 주도한 이 텍스트는 1989년까지 효력을 유지했고, 프라하의 봄은 말해질 수 없는 사건이 되었다.

1989년 벨벳 혁명은 이 침묵을 깼다. 바츨라프 하벨과 알렉산데르 둡체크가 같은 발코니에 선 장면은 1968년과 1989년이 하나의 자유 투쟁의 두 장면이라는 인상을 주었다. 그러나 이 인상은 오래가지 않았다. 1990년대 초 체코에서 집권한 신자유주의 세력은 프라하의 봄을 전혀 다른 방식으로 기억했다. 바츨라프 클라우스의 '모든 제3의 길은 제3세계로 통한다'는 선언은 개혁공산주의자들의 시장과 계획의 결합 구상을 환상으로 일축했다. 젊은 보수 언론인들은 둡체크를 '친절한 수용소 감독관'에 비유했고, 가톨릭 반체제 인사였던 바츨라프 벤다는 1968년이 역사적 전환점이라는 지위 자체를 부정했다.

철학자 카렐 코시크는 이를 두고 프라하의 봄이 '두 번 묻혔다'고 말했다. 1968년 이후 후사크에 의해, 그리고 1989년 이후 신자유주의 정권에 의해. 실제로 1993년의 「공산정권 불법성법」과 2007년의 「전체주의 연구소법」은 1948년부터 1989년까지의 모든 공산주의 통치를 단일한 범죄 체제로 규정함으로써, 1968년의 개혁과 1970년대의 반체제 운동을 구별하지 않았다. 모스크바 의정서 서명을 거부한 유일한 지도자 프란티셰크 크리겔조차 법적 기준으로는 '저항'에 포함되지 않는 모순이 발생했다.

그러나 대중의 기억은 엘리트 담론과 달랐다. 1990년대 중반 여론조사에서 체코 시민의 47%는 프라하의 봄을 민주주의 재건 시도로 보았고, 공산당 내 파벌 투쟁으로 본 응답은 21%에 불과했다. 응답자의 4분의 3은 1968년의 개혁을 '국가적 사안'으로 여겼다. 1968년 8월의 점령은 뮌헨 협정이나 1948년 공산 쿠데타보다 더 큰 국가적 비극으로 인식되었다.

역사학계의 논쟁은 세 가지 축으로 수렴된다. 첫째, 개혁공산주의의 개혁 가능성: 프라하의 봄이 실패할 수밖에 없었는가, 아니면 외부의 무력만이 중단시킬 수 있었던 내재적 전환 과정이었는가. 둘째, 1968년과 1989년의 관계: 프라하의 봄이 벨벳 혁명의 직접적 전사인가, 아니면 공산주의 개혁 불가능성을 입증함으로써 간접적으로 기여했는가. 셋째, 체코와 슬로바키아의 기억 격차: 연방제만이 유일하게 살아남은 개혁이었기에 슬로바키아에서 후사크는 개혁의 파괴자가 아니라 슬로바키아 민족의 평등을 제도화한 정치인으로 기억된다. 이 격차는 1992년 연방 해체 이후 두 나라의 기억 문화가 갈라지는 근거가 되었다.

브레즈네프 독트린의 궤적은 이 논쟁들에 또 하나의 층위를 더한다. 1968년 11월 제정되어 1979년 아프가니스탄에서 재확인된 이 원칙은, 1988년 12월 고르바초프가 유엔에서 '선택의 자유'를 선언하며 공식 폐기되었다. 그러나 프라하의 봄이 제기한 근본 질문, 즉 사회주의 진영 안에서 주권은 어디까지인가, 개혁은 어디서부터 이탈인가는 1989년 이후에도 사라지지 않았다. 약 5만 건의 기록이 체코 당대사연구소의 23권짜리 자료집으로 출간되었고, 소련 측 문서도 상당 부분 개방되었지만, 이 방대한 기록은 합의된 해석보다 더 정교한 질문을 생산했다. 그 질문들이 1968년이 최종적으로 확정하지 못한 유산이다.

## 끝나지 않은 세 질문: 개혁 가능성, 보편성, 그리고 체제의 운명

프라하의 봄이 확정한 것은 적다. 연방제만이 살아남은 유일한 제도적 개혁이고, 나머지는 8월의 전차가 지워갔다. 그러나 프라하의 봄이 제기한 질문들은 확정되지 않은 채 남아 지금도 역사가들을 가르고 있다.

첫째, 개혁공산주의는 애초에 가능한 기획이었는가. 개입이 없었더라도 성공했을 것이라는 주장은 개혁파 자신들의 신념, 즉 국유화가 창출한 사회구조가 이미 되돌릴 수 없는 토대라는 확신에 의존한다. 반대편에서는 개혁이 내부 모순을 안고 있었다고 본다: 당의 지도적 역할을 유지하면서 검열을 폐지하고, 바르샤바조약에 남으면서 독자적 외교를 모색하는 긴장은 침공 이전부터 작동하고 있었다. 역사가 얀 파우에르는 개혁공산주의가 1989년 이후의 민주주의들이 활용할 이론적·제도적 유산을 전혀 남기지 못했다고 단언한다.

둘째, 프라하의 봄은 체코슬로바키아만의 사건이었는가, 보편적 의미를 가졌는가. 이 질문은 1968년 12월 밀란 쿤데라가 『리스티』에 「체코의 운명」을 발표하면서 공론화되었다. 쿤데라는 프라하의 봄이 '사회주의와 자유의 양립'이라는 전인류적 과제에 답하려 한 시도이며, 따라서 체코인과 슬로바키아인이 '세계사의 중심에 섰다'고 주장했다. 이에 바츨라프 하벨은 1969년 2월 『트바르시』에 「체코의 운명?」으로 응답했다: 언론의 자유와 비밀경찰 통제는 '대부분의 문명국에서 당연한 기본 조건'을 회복한 것일 뿐이며, 이것을 세계사적 사명으로 포장하는 것은 '지방적 메시아니즘에 취한 자만'이라고 반박했다. 이 대립은 오늘날까지 이어진다. 유럽에서는 68년을 민주주의와 사회주의의 결합 가능성을 시험한 보편적 순간으로 기억하는 반면, 프라하에서는 그저 실패한 개혁이자 20년 정상화의 서막으로 기억하려는 경향이 강하다.

셋째, 프라하의 봄의 진압은 소련 체제 자체에 무엇을 남겼는가. 가장 급진적인 해석은 개혁의 분쇄가 소련 체제의 붕괴를 예비했다는 역설이다. 1968년 개혁의 설계자였고 모스크바대학 시절 고르바초프의 룸메이트였던 즈데네크 믈리나르시에게 훗날 고르바초프는 이렇게 말했다: "우리는 프라하의 봄을 목졸랐다고 생각했지만, 실은 우리 자신을 목졸랐다." 이 관점에서 보면 개혁을 막은 1968년의 결정은 1985년 이후 개혁이 불가피해졌을 때 소련에 아무런 본보기도, 이론적 자원도, 개혁 경험을 가진 간부도 남기지 않았다. 반대편에서는 소련 체제의 붕괴 원인을 68년에 집중시키는 것이 과잉 결정론이며, 경제 침체, 아프가니스탄, 군비 경쟁 등 다른 요인이 더 컸다고 주장한다.

프라하의 봄이 확정한 것은 단 하나다: 소련식 체제 안에서 개혁의 한계선이 어디인지를 보여주었다는 사실, 그리고 그 한계선을 넘으려는 시도가 체제를 끝내 살아남지 못하게 만들었다는 역설의 가능성이다. 이 역설의 진위를 둘러싼 논쟁이 바로 프라하의 봄이 남긴 가장 깊은 물음이다.$q$ WHERE id = $q$prague-spring$q$;
UPDATE commulingo_history_events SET body_ko = $q$## NATO가 생기기 전, 스탈린의 울타리

1949년 4월 북대서양조약이 워싱턴에서 서명되었을 때, 이오시프 스탈린은 이에 맞설 군사동맹을 만들지 않았다. 만들 필요가 없었기 때문이다. 소련은 이미 동유럽을 장악하고 있었고, 그 장악은 조약 한 장에 의존하지 않았다.

제2차 세계대전에서 소련은 약 2,700만 명의 시민을 잃었다. 독일군은 모스크바 교외까지 진격했고, 레닌그라드는 872일간 포위되었다. 스탈린에게 전후 유럽 문제의 출발점은 이데올로기가 아니라 안보였다: 다시는 소련 영토가 서쪽에서 침공당하는 일이 없어야 한다. 그 해법은 소련 국경과 서유럽 사이에 우호적인 국가들로 이루어진 완충지대를 두는 것이었다.

1945년 4월 21일, 소련과 폴란드 임시정부는 「우호·상호원조 및 전후협력에 관한 조약」에 서명했다. 이보다 앞서 1943년 12월에는 체코슬로바키아 망명정부와 유사한 조약이 체결되어 있었다. 1948년에는 루마니아(2월 4일), 헝가리(2월 18일), 불가리아(3월 18일)와도 동일한 형식의 양자 조약이 체결되었다. 이 조약들의 핵심 조항은 단순했다: 체약국 중 하나가 독일 또는 독일과 연합한 국가의 공격을 받을 경우, 상대방은 즉시 군사적 지원을 포함한 모든 수단으로 원조한다.

이 양자조약 체계는 소련에 완전한 통제권을 부여했다. 각 조약은 모스크바와 해당 수도 사이의 1대1 관계였기에, 동유럽 국가들이 집단적 틀 안에서 공동의 입장을 형성할 가능성은 원천적으로 차단되었다. 역사가 보이테흐 마스트니(Vojtech Mastny)의 표현대로, 스탈린은 자신의 동유럽 종속국들이 "종속자가 아니라 동반자의 지위를 주장할 수 있게 하는 어떤 제도적 장치도" 불신했다. 그가 1943년 코민테른을 해산하고, 1947년 설립한 코민포름마저 3년 만에 유명무실해지도록 방치한 것도 같은 이유에서였다.

실질적 지배력은 조약이 아닌 주둔군에서 나왔다. 1949년 당시 소련군은 동독에만 22개 사단을 주둔시키고 있었고, 폴란드와 헝가리에도 상당한 병력이 배치되어 있었다. 각 인민민주주의 국가의 군대는 소련제 장비로 무장했고, 소련 군사고문단이 각국 국방부에 상주했다. 내무부(NKVD) 후신인 국가보안부(MGB) 고문들도 각국 비밀경찰에 배치되어 있었다. 바르샤바에서 소피아까지, 실질적 주권은 모스크바에 있었다.

경제적 통제기구인 경제상호원조회의(코메콘)는 1949년 1월에 출범했지만, 실질적 기능 없이 명목상으로만 존재했다. 마셜 플랜에 대한 뒤늦은 대응으로 만들어졌으나, 소련은 동유럽에서 자국의 합작기업을 통해 배상금을 추출하는 데 주력했을 뿐 다자간 경제통합에는 관심이 없었다.

이것이 1949년 4월의 상황이었다. NATO가 창설되었을 때, 스탈린은 소련의 정보원들을 통해 NATO가 당분간 실질적 군사력, 즉 통합군 사령부와 배치된 사단을 갖추지 못할 것임을 알고 있었다. 동시에 그는 1948년 유고슬라비아의 요시프 브로즈 티토가 모스크바의 통제에서 이탈하는 사건을 목격한 직후였다. 독자적인 길을 걸을 수 있는 동맹 파트너를 만드는 것보다, 이미 구축된 양자 통제망을 유지하는 편이 훨씬 안전한 선택이었다. 스탈린은 NATO에 맞설 동맹이 아니라, NATO를 분열시키는 데 집중했다.

## 동맹 대신 선택한 것: NATO 갈라놓기

1949년 4월 북대서양조약이 조인됐을 때 스탈린은 맞은편에 자기 동맹을 세우지 않았다. 그에게는 이미 2차대전 중부터 엮어온 양자 우호·상호원조조약 체계가 있었다. 체코슬로바키아는 1943년, 폴란드와 유고슬라비아는 1945년, 루마니아·헝가리·불가리아는 1947~48년에 각각 소련과 조약을 맺어, 동유럽 각국의 군사력이 소련의 지휘 아래 묶여 있었다. 첩보망은 스탈린에게 NATO가 첫 몇 달 동안 서방의 실질 군사력을 늘리지 못한다고 알려주었고, 무엇보다 그는 종속국들이 부하가 아니라 동반자 지위를 요구할 틀을 불신했다. 코민테른을 1943년에 스스로 없앤 것, 코민포름이 1947년 창설 뒤 3년도 못 되어 흐지부지된 것, 코메콘이 빈 껍데기에 머문 것은 모두 같은 성향에서 나왔다. 스탈린은 우중충하고 갓 복속된 동유럽을 관리하기 어려운 동맹으로 묶는 모험 대신, 서방의 동맹을 안쪽에서 깨는 쪽에 힘을 쏟았다. 자본가들 사이의 이익충돌은 화해할 수 없고 이용할 수 있다는 마르크스주의적 확신이 그를 이끌었다.

스탈린이 죽은 뒤에도 이 노선은 바뀌지 않았다. 흐루쇼프는 나중에 "우리는 관성대로 계속 나아갔다. 배는 스탈린이 정한 물길을 그대로 떠내려갔다"고 회고했다. 외교를 맡은 몰로토프는 미국과 서유럽 사이에 쐐기를 박아 NATO를 무력화시키는 전략을 밀었다. 그러나 서방 방위체제는 독일을 종석으로 삼아 착실히 쌓여가고 있었고, 워싱턴은 서독의 군사력을 동원하려는 유럽방위공동체(EDC) 계획까지 밀어붙이고 있었다.

1954년 초 베를린 외무장관회의에서 몰로토프는 미국을 배제하고 NATO를 대체하는 유럽 집단안보조약을 제안했다가 거부당하자, 이번에는 NATO가 소련을 포함한 새 회원국에 문을 열어 스스로 희석되도록 하자고 제안했다. 서방 외무장관들이 "소리 내어 웃자" 몰로토프는 NATO를 없애려는 게 아니라 재무장한 서독이 주도할 EDC를 막으려는 것이라고 해명했다. 소련 외무성은 EDC를 NATO보다 더 위험하게 보았다. 그러나 1954년 8월 30일 프랑스 국민의회가 EDC를 부결시키자, 동맹국들은 불과 두 달도 안 되어 잠자던 서유럽연합(WEU)을 되살려 서독을 뒷문으로 NATO에 들여보냈다. 10월 23일 파리 협정이 서독의 NATO 가입 일정을 못박으면서, 몰로토프의 갈라놓기 전략은 뿌리째 흔들렸다.

## 독일을 놓고 갈라진 크렘린: 모스크바 회의에서 말렌코프 실각까지

파리 협정 서명 한 달 뒤인 1954년 11월 29일 모스크바에서 열린 회의는 겉보기에는 단결의 무대였다. 유럽의 모든 국가와 미국까지 초청했다고 선전했지만, 막상 회의장에 모인 것은 소련과 동유럽 7개국뿐이었고 중국만 참관인으로 앉았다. 몰로토프가 파리 협정을 '유럽 안보에 대한 직접적 위협'이라고 규탄했고, 체코슬로바키아 총리 빌리암 시로키는 처음으로 '특별 안보 조치'를 제의했으며, 참가국들은 서독이 군대를 세우면 동독도 군대를 세우겠다고 선언했다. 그러나 이 선언이 곧바로 동맹 조약으로 이어진 것은 아니었다. 소련 지도부 안에서는 그 전에 풀어야 할 싸움이 있었다.

그 싸움의 초점도 역시 독일이었다. 스탈린이 죽은 직후 말렌코프와 베리야가 짠 구상은 이랬다. 독일의 분단과 동서 양측 군대의 독일 주둔이 소련 외교의 가장 큰 짐이니, 동독 공산정권을 사실상 버리고 질서정연하게 후퇴하면서 서방의 철수와 독일 통일을 맞바꾸자는 것이었다. 1953년 4월 25일 프라우다에 실린 '아이젠하워에게 보내는 답신'은 통일 독일과의 강화조약 체결, 이어서 점령군 철수를 명시했다. 그러나 그해 6월 동베를린에서 봉기가 터지자 이 구상은 흔들렸다. 질서 있는 후퇴가 아니라 와해로 끝날 수 있고, 그것이 동유럽 전체 공산정권을 흔들 수 있다는 인식이 크렘린에 퍼진 것이다.

말렌코프는 독일에서 후퇴하지는 못했어도, 군비 경쟁 자체를 멈추려는 노선은 끝까지 지켰다. 물리학자 쿠르차토프 등에게서 열핵전쟁의 위험을 담은 비밀 보고를 받은 그는 1954년 3월 12일, 원자전쟁은 '세계 문명의 종말'이라고 공개 발언했다. 이는 흐루쇼프와 몰로토프의 날카로운 비판을 불러왔고, 말렌코프는 며칠 뒤 소련도 핵 공격에 보복할 것이라고 철회해야 했다. 같은 해 내내 말렌코프는 소비재 생산과 농민 우대를 앞세워 경공업을 중공업보다 우선했는데, 군부가 잠재적 대서방 전쟁에 불가결하다고 본 중공업을 희생시킨다는 이유로 '우익 일탈'로 공격받았다.

결정타도 독일 문제에서 왔다. 아이작 도이처가 관찰했듯, 스탈린 사후 소련의 두 차례 정부 위기(1953년과 1955년)는 각각 독일에서의 극적 사건 직후에 터졌다. 베리야와 말렌코프의 연합은 1953년 6월 동독 봉기 무렵 무너졌고, 말렌코프와 흐루쇼프의 연합은 런던·파리 협정으로 서독의 NATO 가입이 임박해지자 깨졌다. 1955년 2월 8일 말렌코프는 총리직에서 물러나야 했고, 9일 니콜라이 불가닌이 뒤를 이었다. 공식 비판은 권력 남용과 '결단력 부족', 베리야와의 친분이었지만, 실질은 독일에 대한 노선이었다. 말렌코프의 실각으로 통일 독일에 관한 몰로토프의 구상은 기록 보관소로 들어갔고, 크렘린은 분단 현상 유지를 바탕으로 한 강경 노선으로 굳어졌다. 한 달 뒤 흐루쇼프가 동유럽 당 서기들에게 보낸 다자 동맹 초안은 바로 이 승리한 노선의 산물이었다.

## 군인 없이 쓰인 군사조약: 3월의 초안과 발표

흐루쇼프가 3월 4일 동유럽 각 당 서기들에게 보낸 초안은, 겉보기에는 조약 문안의 전달이었지만 실제로는 훨씬 큰 구상을 싣고 있었다. 그는 다가올 바르샤바 회의를 '유럽 평화와 안전의 보장을 위한 유럽 국가 제2차 회의'라는 틀 속에 넣었다. 그 '제1차 회의'란 지난해 12월의 모스크바 회의, 서방이 참석을 거부해 자기 편끼리만 모인 알량한 모임이었다. 그 후속 자리를 굳이 '평화회의'로 부른 것은, 흐루쇼프가 이 동맹을 처음부터 군사적 대응 그 이상, 곧 서방과 맞교환할 협상 카드로 구상하고 있었음을 맨 처음 문건에서부터 드러낸 셈이다.

서두른 데는 이유가 있었다. 파리 협정의 비준은 이제 거의 확실했고, 1949년 이래 소련이 기대온 'NATO를 내부에서 갈라놓기'라는 묘책은 서독의 NATO 가입이 눈앞에 다가오자 무너져 내렸다. 크렘린은 뒤늦게 자기 편 동맹이라는 카드를 꺼내야 했다. 그런데 바로 이때가, 스탈린 사후 처음으로 동유럽 국가들이 제각기 이해관계를 내세워 모스크바의 방향에 의견을 낼 수 있었던 짧은 틈이었다. 동독은 체코슬로바키아의 지지를 받으며 자기 셋(동독·체코슬로바키아·폴란드)만의 3국 군사협정을 밀었다. 곧 창설될 동독군의 비중을 최대화하려는 계산이었다. 폴란드는 반대로 전체 동맹을 택했다. 폴란드군이 소련군 다음가는 위치를 차지하고, 동독군은 더 단단한 틀에 묶어두는 편이 낫다고 보았기 때문이다. 2월 말 크렘린의 선택은 폴란드 쪽이었다. 초안이 송부된 것도, 바르샤바가 개최지로 정해진 것도 그 연장선이었다.

그러나 '협의'의 실상은 초라했다. 소련 언론이 3월 21일 동맹 계획을 공식 발표했을 때, 그 시점은 프랑스 상원이 파리 협정 비준을 마무리 지을 결정적 표결을 앞둔 때였다. 발표문은 12월 모스크바 회의 참가국들 사이에 '최근의 협의'가 있었다고 적었지만, 실제로 일어난 것은 소련 초안에 대한 동유럽 측의 조심스러운 논평 몇 마디뿐이었다. 그 사이 동유럽 측이 낸 두 제안의 운명이 이 구도의 성격을 잘 보여준다. 동독은 '독일이 통일되면 조약은 무효'라는 선언을 덧붙이자고 조심스레 제안했고, 몰로토프는 서독 내 반NATO 여론을 흔드는 데 도움이 된다며 이를 받아들였다. 반면 폴란드가 '서유럽의 미군 기지 철수 요구'를 조약 전문에 넣자고 한 것은 거부되었다. 그런 요구는 되돌아서 동유럽에 주둔한 소련군의 정당성까지 허물어뜨릴 것이었기 때문이다.

이 모든 과정에서 군대는 끝까지 빠져 있었다. 문서를 쓰고 다듬은 것은 몰로토프의 외무성 보좌진이었다. 군사 전문가가 끼어든 것은 4월 1일, 중앙위원회가 회의 개최를 확정하고서야, 국방장관 주코프에게 통합군령 문서 초안을 '아주 짧은 기한'으로 맡기면서였다. 그때까지도 이 조약이 군사적으로 무엇을 뜻하는지는 아무도 구체화하지 못했다. 바르샤바 조약은 이렇게 전쟁을 준비하는 장군이 아니라 협상을 노리는 정치인과 외교관의 손에서, 한 번의 표결 날짜에 맞추어 태어났다.

## 오래된 조약을 찢고 군축안을 던지다

5월 5일 파리 협정이 발효되자 소련이 보여준 첫 대응은 군대가 아니라 문서였다. 이틀 뒤 모스크바는 2차 대전 당시 서방과 맺었던 우호조약, 곧 1942년의 영소동맹조약과 1944년의 프랑스-소련 동맹조약을 공식 폐기한다고 선언했다. 독일을 공동의 적으로 삼았던 그 법적 유산은 서독이 NATO에 들어간 순간 죽은 문서가 되었고, 소련은 그것을 서둘러 갈무리했다.

그러나 이보다 훨씬 중요한 맞대응은 5월 10일 런던에서 나왔다. 유엔 군축위원회 5개국 소위원회에 소련이 제출한 포괄적 군축안이 그것이다. 이 문건은 핵실험의 유예, 그리고 병력 수준을 비율 삭감이 아니라 정수 상한으로 제한하는 방식 등 모스크바가 그때까지 거부해오던 구상들을 대거 수용했는데, 그 구상들은 미국보다는 영국과 프랑스 쪽에 가까운 것이었다. 기안은 흐루쇼프의 주도로 외무성에서 이루어졌고, 몰로토프의 측근 야코프 말리크가 은근히 방해했다고 기록에 남아 있다. 서방이 무장을 선택한 바로 그 순간, 소련은 군축을 내밀었던 것이다.

이 엇갈림은 크렘린 안의 두 노선을 드러낸다. 보이테흐 마스트니의 정리대로, 몰로토프는 위치의 냉전, 곧 현상의 틀을 지키며 서방의 균열을 기다리는 인물이었다. 반면 흐루쇼프는 움직임의 냉전을 선택했다. 오스트리아 중립화, 유고슬라비아와의 화해, 그리고 이 군축안은 모두 틀을 흔들어 주도권을 쥐려는 같은 수법의 조각들이었다. 바르샤바 조약도 이 흐름 위에 놓여 있었다.

5월 11일 바르샤바 대통령궁에서 열린 회의는 그러한 성격을 그대로 드러냈다. 소련이 미리 마련한 문안은 토론의 외양조차 없이 통과되었고, 수정안이 나와도 사전에 주최국이 주문한 부차적인 것들뿐이었다. 조약 제4조의 상호원조 조항은 NATO 제5조와 달리 '필요하다고 인정하는' 원조만을 규정함으로써 자동적 군사개입을 약속하지 않았다. 독일어본에는 회원국 개개인이 아니라 집단이 결정하리라는 뜻이 담긴 대명사 '그들(sie)'이 조심스럽게 쓰였고, 동독의 발터 울브리히트는 그 차이를 알아챘지만 이의를 삼지 않았다. 무엇보다 군대는 끝까지 뒷자리에 있었다. 국방장관 주코프가 통합군령 문서를 맡은 것은 4월 18일이었고, 회의 마지막 날 병력 할당표는 비공개 회의에서 발표만 되었을 뿐 토론되지 않았다. 군사동맹의 창설 자리에서 가장 늦게 끌려 들어온 것이 바로 군대였다.

## 조약은 서명됐지만, 누구의 동맹이었나

5월 14일 바르샤바에서 서명된 문서는 단순히 NATO의 동쪽 복사본이 아니었다. 소련 대표단이 내세운 명분은 서독의 재무장에 맞선 유럽 집단안보였다. 조약 전문은 모든 유럽 국가가 사회·정치 체제와 무관하게 참여하는 안보체제를 바란다고 선언했고, 파리 협정이 재무장한 서독을 서유럽연합과 NATO에 편입해 “또 다른 전쟁의 위험”을 높였다고 규정했다. 동유럽 정부들에게 이 주장은 추상적 구호만은 아니었다. 독일군의 침공과 점령을 겪은 폴란드와 체코슬로바키아에서는 서독군의 재등장이 국경의 군사적 현실을 바꾼다는 두려움이 컸다. 동독에도 재무장이라는 선택지가 열렸다. 소련은 이를 방어와 평화의 언어로 설명하면서, 서방이 거부한 범유럽 협상안을 아직 포기하지 않았다는 신호도 보냈다.

그러나 조약문을 읽으면 방어의 약속과 지휘권의 비대칭이 함께 보인다. 제4조는 유럽에서 어느 당사국이 공격받으면 각국이 “필요하다고 판단하는 모든 수단”으로 즉시 원조한다고 했지만, 실제 무력 사용을 자동으로 명령하지는 않았다. 반면 제5조는 통합군 사령부를 설치하고 회원국 군대를 그 지휘에 배속할 수 있게 했다. 서명 당일 별도 결의로 통합군 창설이 붙었고, 6월 6일 알바니아가 마지막 비준서를 기탁하자 조약이 발효되었다. 이반 코네프가 첫 총사령관이 되었고 사령부는 모스크바에 놓였다. 정치협의위원회는 각국 정부 대표가 참여하는 협의기관으로 규정됐지만, 일상적인 군사 지휘의 중심은 소련 원수와 소련 참모체계였다. 법률상 동등한 당사국과 실제 작전권 사이에 이미 간극이 생긴 것이다.

회원국들의 계산도 같지 않았다. 소련에게 다자조약은 이미 주둔군과 양자조약으로 확보한 지배를 새 제도 안에 고정하고, 서방 외교에서 NATO와 맞바꿀 수 있는 공식적 상대를 만드는 수단이었다. 동유럽 정부들에게는 서독 재무장에 대한 안전보장과 군사·외교 자원을 얻는 대가로 자국 군대와 외교 선택지를 더 좁히는 계약이었다. 그 양면성은 조약의 수명 조항에서도 드러난다. 제11조는 20년 뒤 10년 연장을 허용했지만, 유럽 일반 집단안보조약이 발효되면 바르샤바 조약도 끝난다고 명시했다. 즉 이 동맹은 영구적인 동서 분할을 선언하면서도, 소련이 주장한 더 넓은 유럽안보 질서로 대체될 여지를 문서 안에 남겼다. 서명과 발효는 하나의 군사기구를 완성했지만, 그 기구가 공동방위의 협의체인지 소련 지휘권의 제도화인지는 처음부터 해결되지 않은 문제였다.

## 바르샤바 조약을 협상 카드로 바꾼 제네바

바르샤바 조약은 서명되는 순간부터 영구적인 동구 군사기구로만 설계된 것은 아니었다. 1955년 7월 제네바에서 소련 대표단이 내놓은 것은 조약을 지키겠다는 선언이 아니라, 조약을 더 큰 유럽 질서와 맞바꾸자는 거래였다. 소련 총리 니콜라이 불가닌은 독일 문제와 유럽 안보를 분리할 수 없다고 주장했다. 서독이 북대서양조약기구에 들어간 상태에서 독일 통일을 추진하면 통일 독일이 서방 군사권에 편입될 것이므로, 먼저 긴장을 낮추고 두 독일을 기존 군사블록의 의무에서 풀어야 한다는 논리였다. 소련안의 최대 목표는 미국과 캐나다를 포함한 유럽 집단안보조약을 만들어 NATO와 바르샤바 조약을 동시에 폐기하는 것이었다. 현실적인 차선책으로는 양쪽 동맹 회원국 사이에 불가침조약을 맺자는 방안도 제시했다. 이 구상은 소련이 동유럽을 포기하겠다는 뜻이 아니었다. 동독이 서독처럼 서방 동맹에 편입되는 것을 막고, 독일의 군사적 방향을 통제할 시간을 확보하려는 방어적 계산이었다. 소련 지도부가 보기에는 새 조약이 바로 그 협상력을 만들어 주었다.

서방은 같은 문장을 다르게 읽었다. 영국 총리 앤서니 이든은 유럽 전체의 안보체제가 합의되기까지 시간이 너무 오래 걸리므로, 통일 독일을 네 강대국과 공동으로 보장하는 더 단순한 방식을 먼저 검토하자고 했다. 미국 대통령 드와이트 아이젠하워는 NATO를 전쟁 준비기구가 아니라 평화를 위한 방어동맹으로 설명하면서, 서독군을 서방군에 묶어 독자적인 침략능력을 갖지 못하게 했다고 주장했다. 그가 7월 21일 내놓은 오픈 스카이스 계획은 상호 항공정찰로 군사시설을 감시하자는 제안이었다. 소련은 주권 침해와 정찰 악용을 우려해 이를 거부했고, 미국은 소련의 집단안보안이 NATO를 해체시키면서도 소련의 동유럽 지배는 건드리지 않는다고 보았다. 실제로 미국 대표단의 회의 기록에서 아이젠하워는 동유럽 위성국 문제와 국제공산주의 문제를 회담 의제로 삼아야 한다고 요구했지만, 불가닌은 이를 뒤로 미루려 했다.

제네바의 미소는 그래서 합의의 증거이면서 교착의 기술이었다. 정상들이 10년 만에 마주 앉았다는 사실은 긴장을 낮췄지만, 독일의 중립을 누가 보장하고 동유럽의 선택권을 누가 결정할지는 해결하지 못했다. 소련은 바르샤바 조약을 NATO의 영구적 복제품이라기보다 폐기 가능한 대항물로 사용했으나, 서방이 그 교환을 받아들이지 않으면서 조약은 남았다. 그 결과 바르샤바 조약은 처음 의도한 유럽 집단안보의 임시 발판이 아니라, 분단을 협상으로 끝내지 못한 대륙의 상설 제도가 되었다.

## 완성한 것은 양극화, 남겨 둔 것은 유럽의 안전

바르샤바 조약이 1955년에 확정한 것은 유럽의 안전이 아니라 안전을 말하는 두 개의 정치적 진영이었다. 서독의 NATO 가입에 맞서 소련과 동유럽 7개국은 공동방위의 법적 형식을 갖추었고, 소련은 서방과 협상할 때 NATO와 대등한 상대라는 외관도 얻었다. 회원국의 입장에서 이 선택은 단순한 위성국의 복종만은 아니었다. 나치 독일의 침략을 겪은 폴란드와 체코슬로바키아에게 서독 재무장은 실제 위협으로 보였고, 동독 지도부에게 군대와 국가의 국제적 승인은 생존의 표지였다. 그러나 그 방위는 주권의 대가를 요구했다. 조약 제8조는 독립과 내정불간섭을 약속했지만, 1956년 소련군의 헝가리 개입과 1968년 체코슬로바키아 침공은 회원국 정부가 사회주의 노선에서 벗어날 때 그 약속이 작동하지 않음을 드러냈다. 1968년 개입에는 루마니아가 참여하지 않았고, 알바니아는 그해 탈퇴했다. 조약은 외부 공격에 대한 자동적인 공동전쟁의 실제 시험을 끝내 치르지 않았지만, 내부 정치의 한계를 설정하는 도구로는 작동했다.

그렇다고 창설을 처음부터 국내 억압 장치였다고만 부를 수도 없다. 1955년 5월 14일 조약 제11조는 모든 유럽 국가가 참여하는 일반 유럽 집단안보조약이 발효하면 바르샤바 조약도 끝난다고 명시했다. 소련 지도부가 제네바에서 NATO와 바르샤바 조약을 함께 해체하자고 제안한 기록은 이 조항이 단순한 장식만은 아니었음을 보여준다. 소련이 기대한 것은 서독 재무장을 저지하거나 그 비용을 높이고, 유럽 전체의 안전보장 협상에서 서방과 힘의 균형을 확보하는 일이었다. 그 기대는 서방의 거부와 독일 분단의 고착 앞에서 실현되지 않았다.

역사학의 쟁점은 바로 이 두 기능의 우선순위다. 보이테흐 마스트니는 공개 자료와 동독·폴란드·체코 기록을 대조해 조약이 군사동맹이라기보다 외무성 중심의 정치적 사업이었고, 창설 당시에는 이미 존재하던 소련의 양자조약과 주둔군 때문에 군사적으로 상당히 불필요했다고 설명한다. 반대편 해석은 서독의 재무장과 NATO 편입이라는 물질적 변화가 소련과 동유럽 국가들에게 통합지휘와 동독군 편입을 더 이상 미룰 수 없게 했다고 본다. 두 해석은 서로 배타적이지 않다. 바르샤바 조약은 전쟁을 막는 군사동맹으로서는 제한적이었지만, 동유럽의 군사력과 외교를 하나의 위계에 묶고 서방과의 협상 단위를 만든 제도였다. 1991년 해체가 보여준 것도 단순한 군사적 패배가 아니다. 소련이 더는 그 위계를 유지할 정치적 힘을 행사하지 못하자, 공동방위의 언어와 제국적 통제의 구조가 함께 무너진 것이다.$q$ WHERE id = $q$warsaw-pact$q$;
UPDATE commulingo_history_events SET outcome_ko = $q$군사 점령으로 개혁은 중단되고 「정상화」라 불린 억압적 원상복구가 이어졌다. 소련은 사회주의 진영 국가의 주권을 제한할 수 있다는 「브레즈네프 독트린」으로 개입을 정당화했다. 둡체크는 밀려나 산림청 직원으로 보내졌고, 프라하의 봄은 진영 안 개혁의 한계를 다시 한번 확인시켰다.$q$ WHERE id = $q$prague-spring$q$;
